/* DAWAH X — ahmad, অধ্যায় 41 · খণ্ড 41 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][41]=[[8001,8001,"","বাবার ছেলে মারা যাওয়ার ব্যাপারে বাবা আমাকে মেরে ফেলতে চায়। বাবা বাবা, ঈশ্বরের জন্য প্রার্থনা করে, কিন্তু সেই মিথিলাকে আমি ভুলতে পারবো না। কিন্তু, আমি আমার বাবার ছেলের কাছে এই অবস্থা বুঝতে পারিনি। আমি যদি আমার বাবার ছেলের ছেলের ছেলের কাছে ফিরে যাই, তাহলে সে আমাকে খুন করতে হবে। কিন্তু আমি জানি, সে আমাকে কি করেছে? আমি জানি, আমি কি করেছি? যদি তুমি তাকে সমাধান করতে চাও তাহলে তার কথা শেষ করতে পারবে না, আর তারাই হবে সেই লোক যারা তাকে মেরে ফেলবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏وَإِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ سَمْعَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏أَبَا قَتَادَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُبَايَعُ لِرَجُلٍ بَيْنَ الرُّكْنِ ‏ ‏وَالْمَقَامِ ‏ ‏وَلَنْ يَسْتَحِلَّ ‏ ‏الْبَيْتَ ‏ ‏إِلَّا أَهْلُهُ فَإِذَا اسْتَحَلُّوهُ فَلَا تَسْأَلْ عَنْ هَلَكَةِ ‏ ‏الْعَرَبِ ‏ ‏ثُمَّ تَأْتِي ‏ ‏الْحَبَشَةُ ‏ ‏فَيُخَرِّبُونَهُ خَرَابًا لَا يَعْمُرُ بَعْدَهُ أَبَدًا وَهُمْ الَّذِينَ يَسْتَخْرِجُونَ كَنْزَهُ ‏","","",""],[8002,8002,"","আমি বাবার সঙ্গে আমার বাবার বাবার বাবার বাবার বাবার বাবার বাবার বিষয়ে কথা বলেছিলাম । আমার সব পিতাই ছিলেন আমার বাবা আর মা ছিলেন অসভ্য আর অবিশ্বাস্য।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَنْعَتُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كَانَ ‏ ‏شَبْحَ الذِّرَاعَيْنِ أَهْدَبَ ‏ ‏أَشْفَارِ ‏ ‏الْعَيْنَيْنِ بَعِيدَ مَا بَيْنَ ‏ ‏الْمَنْكِبَيْنِ ‏ ‏يُقْبِلُ جَمِيعًا ‏ ‏وَيُدْبِرُ ‏ ‏جَمِيعًا بِأَبِي هُوَ وَأُمِّي لَمْ يَكُنْ ‏ ‏فَاحِشًا ‏ ‏وَلَا ‏ ‏مُتَفَحِّشًا ‏ ‏وَلَا ‏ ‏صَخَّابًا ‏ ‏فِي الْأَسْوَاقِ ‏","","",""],[8003,8003,"","আমরা আমার বাবাকে একজন উৎপীড়ক হিসেবে বলেছি, তাকে দোষ দিতে হবে যে সে তার ব্যর্থতার জন্য তোমাকে অভিযুক্ত করবে। আমার প্রার্থনা শুনে তুমি তার টাকা চুরি করতে পারো, তোমার নিজের দুনিয়া থেকে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ ثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ ذَكَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ الْعَبْدَ الْمَمْلُوكَ لَيُحَاسَبُ بِصَلَاتِهِ فَإِنْ نَقَصَ مِنْهَا شَيْئًا قِيلَ لَهُ نَقَصْتَ مِنْهَا فَيَقُولُ يَا رَبِّ سَلَّطْتَ عَلَيَّ مَلِيكًا شَغَلَنِي عَنْ صَلَاتِي فَيَقُولُ قَدْ رَأَيْتُكَ تَسْرِقُ مِنْ مَالِهِ لِنَفْسِكَ فَهَلَّا سَرَقْتَ لِنَفْسِكَ مِنْ عَمَلِكَ أَوْ عَمَلِهِ قَالَ فَيَتَّخِذُ اللَّهُ عَلَيْهِ الْحُجَّةَ ‏","","",""],[8004,8004,"","আমরা আমার বাবার কথা বলেছিলাম কিন্তু বাবার থেকে ভালো বলতে চেষ্টা করছিল সে এটা বলেনি, ঈশ্বর তাকে আদেশ দিয়েছেন আর সে আমার বাবার ছেলের সব সিঁড়ি বলে দিয়েছে, কিন্তু সে তোমার বাবার বাবার সব সিঁড়ি বলে দিয়েছে। ঈশ্বর তাকে আদেশ দিয়েছেন, যেন আপনার প্রভুর অনুগ্রহে... ...আর আপনি সেই কাপুরুষের মত কথা বলছেন যে ঐ ফাটলী বন্ধু যে কথা বলেছিল এটা।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ بْنُ فُضَالَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَا أَعْلَمُهُ إِلَّا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كُلُّ ‏ ‏سُلَامَى ‏ ‏مِنْ ابْنِ ‏ ‏آدَمَ ‏ ‏صَدَقَةٌ حِينَ يُصْبِحُ فَشَقَّ ذَلِكَ عَلَى الْمُسْلِمِينَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ سَلَامَكَ عَلَى عِبَادِ اللَّهِ صَدَقَةٌ ‏ ‏وَإِمَاطَتَكَ ‏ ‏الْأَذَى عَنْ الطَّرِيقِ صَدَقَةٌ وَإِنَّ أَمْرَكَ بِالْمَعْرُوفِ صَدَقَةٌ وَنَهْيَكَ عَنْ الْمُنْكَرِ صَدَقَةٌ ‏ ‏وَحَدَّثَ أَشْيَاءَ مِنْ نَحْوِ هَذَا لَمْ أَحْفَظْهَا ‏","","",""],[8005,8005,"","আমরা আমার বাবা একজন উৎপীড়ক ছিলেন যিনি তাকে শুনেছেন। তিনি বলেছেন, যখন লাইব্রেরিওয়ালা ঋণের মধ্যে থাকে, তখন ঋণের হার কম হবে। তারা মুক্ত হয়ে যাবে.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّمَا يَلْبَسُ الْحَرِيرَ فِي الدُّنْيَا مَنْ لَا يَرْجُو أَنْ يَلْبَسَهُ فِي الْآخِرَةِ إِنَّمَا يَلْبَسُ الْحَرِيرَ مَنْ لَا خَلَاقَ لَهُ ‏ ‏قَالَ ‏ ‏الْحَسَنُ ‏ ‏فَمَا بَالُ أَقْوَامٍ يَبْلُغُهُمْ هَذَا عَنْ نَبِيِّهِمْ فَيَجْعَلُونَ حَرِيرًا فِي ثِيَابِهِمْ وَفِي بُيُوتِهِمْ ‏","","",""],[8006,8006,"","আমি আমার বাবার সাথে কুতামা হয়ে কথা বলেছি আর আমি তাকে ভালবাসতে শেখাচ্ছি না, আমাকে দেখতে হবে আর আমরা আশাটি জিতেছি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَلَا أَعْلَمُهُ إِلَّا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعَيْنُ تَزْنِي وَالْقَلْبُ يَزْنِي فَزِنَا الْعَيْنِ النَّظَرُ وَزِنَا الْقَلْبِ التَّمَنِّي وَالْفَرْجُ يُصَدِّقُ مَا هُنَالِكَ أَوْ يُكَذِّبُهُ ‏","","",""],[8007,8007,"","আমরা আমার বাবা একজন উৎপীড়ক বা আমার ঘোড়াকে আমার যাজকের চেয়ে ভালো বলে উল্লেখ করেছি। ভগবান নিজেকে একজন কিশোরের মত আত্মসমর্পণ করেছেন, আমি প্রতি মাসে তিন দিন এবং তিন দিনই তাদেরাশ হতে দিতে পারি না। কখনো ঘুমোবে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَوْصَانِي خَلِيلِي ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِثَلَاثٍ لَا أَدَعُهُنَّ ‏ ‏صَوْمِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ وَأَنْ لَا أَنَامَ إِلَّا عَلَى ‏ ‏وِتْرٍ ‏ ‏وَالْغُسْلِ يَوْمَ الْجُمُعَةِ ‏","","",""],[8008,8008,"","ক্ষমার জীবন ছেড়ে দেওয়ার চেয়ে আমরা আরও ভালো কাজ করেছি। কিন্তু আমার পিতা, আমার সহায়, তিনি বলেছিলেন প্রভুর কাছে প্রার্থনা করেছেন। রাতের বেলা প্রার্থনা করার প্রতিজ্ঞা করে তিনি বলেছিলেন যে যুবক - যুবতীরাও একই পছন্দ করবে ।","‏ ‏حَدَّثَنَا ‏ ‏الْحُسَيْنُ بْنُ عَلِيٍّ الْجُعْفِيُّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْتَشِرِ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ الْحِمْيَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَتَى رَجُلٌ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَيُّ الصَّلَاةِ ‏ ‏أَفْضَلُ بَعْدَ الْمَكْتُوبَةِ قَالَ الصَّلَاةُ فِي جَوْفِ اللَّيْلِ قَالَ فَأَيُّ الصِّيَامِ أَفْضَلُ بَعْدَ رَمَضَانَ قَالَ شَهْرُ اللَّهِ الَّذِي تَدْعُونَهُ الْمُحَرَّمَ ‏","","",""],[8009,8009,"","আমরা আমার বাবা হিরোইন হওয়ার কথা বলেছিলাম, তাকে তাড়াতাড়ি করতে বলেছিলেন, যে পর্যটকদের নিয়ে গিয়েছিল সে আমাদের উদ্ধার করেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَمَلَ السِّلَاحَ عَلَيْنَا فَلَيْسَ مِنَّا ‏","","",""],[8010,8010,"","আমরা বাবার সাথে আমার ছেলের সম্পর্কে কথা বলেছিলাম তিনি বললেন, ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তিনি ঈশ্বরের সমবেদনা প্রদান করবেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏قُرَّةُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏إِنَّ أَحَبَّ عِبَادِي إِلَيَّ أَعْجَلُهُمْ فِطْرًا ‏","","",""],[8011,8011,"","আমি আমার বাবার কাছে একজন ব্যক্তিকে বলেছিলাম । দুই বা পাঁচ ঈশ্বরের সর্বশ্রেষ্ঠ দেবতা, সবথেকে ভালো অথবা সবকিছুর জন্য।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ رِفَاعَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ أَكْثَرَ مَا يَصُومُ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسَ قَالَ فَقِيلَ لَهُ قَالَ فَقَالَ ‏ ‏إِنَّ الْأَعْمَالَ تُعْرَضُ كُلَّ اثْنَيْنِ وَخَمِيسٍ ‏ ‏أَوْ كُلَّ يَوْمِ اثْنَيْنِ وَخَمِيسٍ ‏ ‏فَيَغْفِرُ اللَّهُ لِكُلِّ مُسْلِمٍ ‏ ‏أَوْ لِكُلِّ مُؤْمِنٍ ‏ ‏إِلَّا الْمُتَهَاجِرَيْنِ فَيَقُولُ أَخِّرْهُمَا ‏","","",""],[8012,8012,"","আমরা বাবার সাথে কথা বলেছি ডার্ক ওয়ানের মত গোয়া হওয়ার চেয়ে। আমি তার বাবাকে বলতে শুনেছি যে সে লর্ডের কাছে প্রার্থনা করছে তার হাত দিয়ে তার হাত রক্ষা করুন। পরিষ্কার কোন কাজের না, কিন্তু আগুন দেওয়ার কোন উপায় নেই।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ يَزِيدَ بْنِ فَرُّوخَ الضَّمْرِيُّ ‏ ‏مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏أَشْهَدُ لَسَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ عَبْدٍ أَوْ أَمَةٍ يَحْلِفُ عِنْدَ هَذَا الْمِنْبَرِ عَلَى يَمِينٍ ‏ ‏آثِمَةٍ ‏ ‏وَلَوْ عَلَى سِوَاكٍ رَطْبٍ إِلَّا وَجَبَتْ لَهُ النَّارُ ‏","","",""],[8013,8013,"","আমরা বাবার পর্দা নিয়ে কথা বলেছি, যে আমাকে ধ্বংস করার চেষ্টা করেছে, কিন্তু আমি নিশ্চিত যে আমি নই। সে ঈশ্বরের কাছে প্রার্থনা করলো, সে তোমাকে কখনোই বিশ্বাস করবে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ جَعْفَرٍ ‏ ‏حَدَّثَنِي ‏ ‏عِمْرَانُ بْنُ أَبِي أَنَسٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْحَكَمِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَفْرَكُ مُؤْمِنٌ مُؤْمِنَةً إِنْ كَرِهَ مِنْهَا خُلُقًا رَضِيَ مِنْهَا آخَرَ ‏","","",""],[8014,8014,"","আমরা কথা বলেছি যে আমরা যে বিশাল আবেগ নিয়ে কথা বলেছি কিন্তু যুদ্ধ আমার অনুভূতি নিয়ে। তিনি বলেছেন, তিনি তাঁর জন্য প্রার্থনা করেছেন এবং তিনি রাত পর্যন্ত রাতে এবং আপনার জন্য কোন দিন পর্যন্ত যাবেন না। যে মানুষ হিসেবে তাকে বলা হবে সে একজন মানুষ হিসেবে... ...সে একজন মানুষ যে হবে সে হবে... ...আর সে হবে একজন মানুষ যে প্রভুর লোক।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْحَكَمِ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَذْهَبُ اللَّيْلُ وَالنَّهَارُ حَتَّى يَمْلِكَ رَجُلٌ مِنْ الْمَوَالِي يُقَالُ لَهُ ‏ ‏جَهْجَاهُ ‏","","",""],[8015,8015,"","যখন এটা ঘটেছিল তখন আমরা আমার উষ্ণতার কথা বলেছিলাম, এটা গোপন যে ডিলাররা বাইরে গিয়েছে আর তাদের নিজের অধিকার অনুযায়ী ব্যবসা করার অনুমতি দেয়া হবে ভগবানকে বিক্রি করার অনুমতি দেয়া হয়েছে, ঈশ্বরের কাছে প্রার্থনা করতে হবে যেন তিনি প্রভুর জন্য আনন্দ লাভ করেন, প্রহরীদের পিছনে যেতে পারেন, তারা মাছগুলোকে আমার হাত থেকে সরিয়ে দেবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ عُثْمَانَ ‏ ‏حَدَّثَنِي ‏ ‏بُكَيْرُ بْنُ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏أَنَّ ‏ ‏صِكَاكَ ‏ ‏التُّجَّارِ خَرَجَتْ فَاسْتَأْذَنَ التُّجَّارُ ‏ ‏مَرْوَانَ ‏ ‏فِي بَيْعِهَا فَأَذِنَ لَهُمْ فَدَخَلَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏عَلَيْهِ فَقَالَ لَهُ أَذِنْتَ فِي بَيْعِ الرِّبَا وَقَدْ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يُشْتَرَى الطَّعَامُ ثُمَّ يُبَاعَ حَتَّى ‏ ‏يُسْتَوْفَى ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏فَرَأَيْتُ ‏ ‏مَرْوَانَ ‏ ‏بَعَثَ الْحَرَسَ فَجَعَلُوا يَنْتَزِعُونَ ‏ ‏الصِّكَاكَ ‏ ‏مِنْ أَيْدِي مَنْ لَا يَتَحَرَّجُ مِنْهُمْ ‏","","",""],[8016,8016,"","আমরা কথা বলেছিলাম বড় ছেলে হবার জন্য আমরা কত ভালোবাসা নিয়ে কথা বলেছি। আমার বাবা একটা উপহার যেটা আমি মানুষকে ঈশ্বরের অনুগ্রহ হিসেবে দেখেছিলাম, সেটা তিনি বলেছিলেন। শহরের লোকেরা বলেছিল যে তিনি চলে যাবেন। তিনি ভয় পেয়ে যান, প্রথমে দুটো বাঁধা এবং ঘন দুটি অংশ পড়ার জন্য হয় । ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং এই মুখ থেকে আত্মসমর্পণ করেছেন যার মানে আমি ভিকটিমকের পর্দার উপর দিয়ে গিয়েছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا رَأَيْتُ رَجُلًا أَشْبَهَ ‏ ‏صَلَاةً بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ فُلَانٍ ‏ ‏لِإِمَامٍ كَانَ ‏ ‏بِالْمَدِينَةِ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ بْنُ يَسَارٍ ‏ ‏فَصَلَّيْتُ خَلْفَهُ فَكَانَ ‏ ‏يُطِيلُ الْأُولَيَيْنِ مِنْ الظُّهْرِ وَيُخَفِّفُ الْأُخْرَيَيْنِ وَيُخَفِّفُ الْعَصْرَ وَيَقْرَأُ فِي الْأُولَيَيْنِ مِنْ الْمَغْرِبِ بِقِصَارِ ‏ ‏الْمُفَصَّلِ ‏ ‏وَيَقْرَأُ فِي الْأُولَيَيْنِ مِنْ الْعِشَاءِ مِنْ وَسَطِ ‏ ‏الْمُفَصَّلِ ‏ ‏وَيَقْرَأُ فِي الْغَدَاةِ بِطُوَالِ ‏ ‏الْمُفَصَّلِ ‏ ‏قَالَ ‏ ‏الضَّحَّاكُ ‏ ‏وَحَدَّثَنِي ‏ ‏مَنْ سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏مَا رَأَيْتُ أَحَدًا أَشْبَهَ صَلَاةً بِصَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ هَذَا الْفَتَى ‏ ‏يَعْنِي ‏ ‏عُمَرَ بْنَ عَبْدِ الْعَزِيزِ ‏ ‏قَالَ ‏ ‏الضَّحَّاكُ ‏ ‏فَصَلَّيْتُ خَلْفَ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏وَكَانَ يَصْنَعُ مِثْلَ مَا قَالَ ‏ ‏سُلَيْمَانُ بْنُ يَسَارٍ ‏","","",""],[8017,8017,"","আমি বাবার সাথে কথা বলেছিলাম, আমার বাবার সাথে আমাকে খুশি করার চেষ্টা করে তিনি বললেন, ঈশ্বর তার কাছে প্রার্থনা করেন এবং আত্মসমর্পণ করেন যে তিনি যেতে চান না। সবচেয়ে ভালো হল তিনি বলেছেন দুর্ঘটনা থেকে মুক্তি পেতে। আমি জানি না। আমি কি জানি? আমি জানি না। আমি যদি আমার বাবা আমাকে এই সিদ্ধান্তের জন্য অপেক্ষা করে থাকেন, আমি জানি যে, আমি জানি, আমি কি বলছি, আমি জানি না যে, আমি যদি আমি এটা করতে পারি, আমি এটা আমার বাবা আমাকে ছেড়ে চলে যেতে হবে। আমি যদি আমার বাবা আমাকে ছেড়ে চলে যেতে দেন, আমি জানি যে আমি জানি, আমি এই সিদ্ধান্ত নিয়েছি, আমি জানি না। আমি যদি আমার বাবা আমাকে ছেড়ে দেয়, আমি এই ব্যাপারে রাজি হয়ে যাই। আমি জানি যে, আমি যদি আমার বাবা আমাকে ছেড়ে দেয়, আমি জানি যে, আমি আমার বাবা আমাকে ছেড়ে দেবে। আমি যদি আমার বাবা আমাকে এই বিষয়ে কিছু করতে না দেয়, তাহলে আমি তাকে জিজ্ঞেস করেন, আমাকে জিজ্ঞেস করো, তুমি আগুন থেকে বেরিয়ে আসতে ক্লান্ত হয়ে পড়বে আর খুন হতে যাচ্ছ, নাকি আমি তাকে থামাব?","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏حَدَّثَنِي ‏ ‏مُعَاوِيَةُ بْنُ أَبِي مُزَرِّدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمِّي ‏ ‏سَعِيدٌ أَبُو الْحُبَابِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَمَّا خَلَقَ الْخَلْقَ قَامَتْ الرَّحِمُ فَأَخَذَتْ ‏ ‏بِحَقْوِ ‏ ‏الرَّحْمَنِ قَالَتْ هَذَا مَقَامُ الْعَائِذِ مِنْ الْقَطِيعَةِ قَالَ أَمَا تَرْضَيْ أَنْ أَصِلَ مَنْ وَصَلَكِ وَأَقْطَعَ مَنْ قَطَعَكِ اقْرَءُوا إِنْ شِئْتُمْ ‏ { ‏فَهَلْ عَسَيْتُمْ إِنْ تَوَلَّيْتُمْ أَنْ تُفْسِدُوا فِي الْأَرْضِ وَتُقَطِّعُوا أَرْحَامَكُمْ أُولَئِكَ الَّذِينَ لَعَنَهُمْ اللَّهُ فَأَصَمَّهُمْ وَأَعْمَى أَبْصَارَهُمْ أَفَلَا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا ‏}","","",""],[8018,8018,"","আমি দুঃখিত, ঈশ্বর তাকে শিক্ষা দিয়েছেন এবং তাঁর পতাকার শপথ নিয়ে দিয়েছেন। আমার কাছে এমন দুটো ষড়যন্ত্রকারী নেই যারা আপনার বিশ্বাসে বিশ্বাসীদের হারানোর জন্য বিখ্যাত। সত্য বিশ্বাস করার প্রতিজ্ঞা, মানুষের ঘুম আর তাদের ধার বিশ্বাসের মঠ।","‏ ‏أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏قَالَ ثَنَا ‏ ‏كَثِيرُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَحْلُوفُ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَتَى عَلَى الْمُسْلِمِينَ شَهْرٌ خَيْرٌ لَهُمْ مِنْ رَمَضَانَ وَلَا أَتَى عَلَى الْمُنَافِقِينَ شَهْرٌ شَرٌّ مِنْ رَمَضَانَ وَذَلِكَ لِمَا يُعِدُّ الْمُؤْمِنُونَ فِيهِ مِنْ الْقُوَّةِ لِلْعِبَادَةِ وَمَا يُعِدُّ فِيهِ الْمُنَافِقُونَ مِنْ غَفَلَاتِ النَّاسِ وَعَوْرَاتِهِمْ هُوَ غَنْمٌ وَالْمُؤْمِنُ يَغْتَنِمُهُ الْفَاجِرُ ‏","","",""],[8019,8019,"","ঈশ্বর তাকে আদেশ দিয়েছেন আর আমি আপনাকে তার সঙ্গে মেলামেশা করতে বলি যদি তিনি সেখানে আসেন এবং তিনি তা করেছিলেন । না, আমি তার প্রার্থনার জন্য তাকে গুলি করব যদি আমি এর সাথে কিছু করতে চাই, সে সন্দেহ করে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَحَدَكُمْ إِذَا كَانَ فِي الصَّلَاةِ جَاءَهُ الشَّيْطَانُ ‏ ‏فَأَبَسَ ‏ ‏بِهِ كَمَا ‏ ‏يَأْبِسُ ‏ ‏الرَّجُلُ بِدَابَّتِهِ فَإِذَا سَكَنَ لَهُ أَضْرَطَ بَيْنَ أَلْيَتَيْهِ لِيَفْتِنَهُ عَنْ صَلَاتِهِ فَإِذَا وَجَدَ أَحَدُكُمْ شَيْئًا مِنْ ذَلِكَ فَلَا يَنْصَرِفْ حَتَّى يَسْمَعَ صَوْتًا أَوْ يَجِدَ رِيحًا لَا يُشَكُّ فِيهِ ‏","","",""],[8020,8020,"","আমরা নরকের মহান পিতাকে সাহায্য করার ব্যাপারে কথা বলেছিলাম। ঈশ্বর তাঁর কাছে প্রার্থনা করেছিলেন এবং তাঁর মঙ্গলভাবের আদালতে থাকলে আমি আপনাকে আত্মসমর্পণ করবো। তার বাবা ছিল একজন ভালো মানুষ যে তোমাকে ছেড়ে চলে গিয়েছিল বা সে ভালো মানুষ হবে না. অথবা তার চকমটা ঈশ্বরের মনে থাকবে না.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَحَدَكُمْ إِذَا كَانَ فِي الْمَسْجِدِ جَاءَهُ الشَّيْطَانُ ‏ ‏فَأَبَسَ ‏ ‏بِهِ كَمَا ‏ ‏يَأْبِسُ ‏ ‏الرَّجُلُ بِدَابَّتِهِ فَإِذَا سَكَنَ لَهُ زَنَقَهُ ‏ ‏أَوْ ‏ ‏أَلْجَمَهُ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَأَنْتُمْ تَرَوْنَ ذَلِكَ أَمَّا الْمَزْنُوقُ فَتَرَاهُ مَائِلًا كَذَا لَا يَذْكُرُ اللَّهَ وَأَمَّا ‏ ‏الْمَلْجُومُ ‏ ‏فَفَاتِحٌ فَاهُ لَا يَذْكُرُ اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[8021,8021,"","আমরা কয়েক বছর আগে ঈশ্বর আমাকে সুখী করেছেন বলে কথা বলেছি, আমি ঈশ্বরের কাছে প্রার্থনা করব আর সে মানুষের পাপ উদ্ধার করবে আর তারপর সে উল্লেখ করলো যে ঈশ্বর এবং ঈশ্বরের প্রতি বিশ্বাস আমি ঈশ্বরের কাজ করেছি, একজন মানুষ বলেছে যে আমাকে হত্যা করা হয়েছে আর আমরা একটি ভাল ছেলে, আমি বলতে চাচ্ছি যে, আমরা ঘুমিয়ে পড়ি, \"সে বলল যে আমি ঈশ্বরের পথে মারা গেছি এবং আমরা একজন ভালো ছেলে। সে বলল যে আমি ঈশ্বরের পথে খুন হয়েছি এবং আমরা হলাম স্বল্পমেয়াদী রোগী, এই ঋণ হচ্ছে গ্যাব্রিয়েল আমার কাছে প্রার্থনা করেছে। আমি জানি, আমি আল্লাহ্‌র পথে আমি খুন হয়েছি। আর আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি না যে আমি মারা যাচ্ছি। আমি সত্যিই অনেক ভালো। এবং আমি জানি, আমি জানি, তুমি.","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي سَرْحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ فَخَطَبَ النَّاسَ ثُمَّ ذَكَرَ ‏ ‏أَنَّ الْإِيمَانَ بِاللَّهِ وَالْجِهَادَ فِي سَبِيلِ اللَّهِ مِنْ أَفْضَلِ الْأَعْمَالِ عِنْدَ اللَّهِ فَقَامَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ وَأَنَا صَابِرٌ مُحْتَسِبٌ مُقْبِلٌ غَيْرُ ‏ ‏مُدْبِرٍ ‏ ‏يُكَفِّرُ اللَّهُ عَنِّي خَطَايَايَ قَالَ نَعَمْ فَكَيْفَ قُلْتَ قَالَ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ وَأَنَا صَابِرٌ مُحْتَسِبٌ مُقْبِلٌ غَيْرُ ‏ ‏مُدْبِرٍ ‏ ‏يُكَفِّرُ اللَّهُ عَنِّي خَطَايَايَ قَالَ نَعَمْ كَيْفَ قُلْتَ قَالَ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ وَأَنَا صَابِرٌ مُحْتَسِبٌ مُقْبِلٌ غَيْرَ ‏ ‏مُدْبِرٍ ‏ ‏يُكَفِّرُ اللَّهُ عَنِّي خَطَايَايَ قَالَ نَعَمْ إِلَّا الدَّيْنَ فَإِنَّ ‏ ‏جِبْرِيلَ ‏ ‏سَارَّنِي بِذَلِكَ ‏","","",""],[8022,8022,"","আমি আমার বাবাকে ছেড়ে চলে যাওয়ার সিদ্ধান্ত নিই । তোমার মৃত্যু পছন্দ হয়েছে আর আমি তোমার উপর ভর করেছি।","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏قَالَ ثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِلْعَبْدِ الْمُصْلِحِ الْمَمْلُوكِ أَجْرَانِ ‏ ‏وَالَّذِي نَفْسُ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏بِيَدِهِ لَوْلَا الْجِهَادُ فِي سَبِيلِ اللَّهِ وَالْحَجُّ ‏ ‏وَبِرُّ ‏ ‏أُمِّي ‏ ‏لَأَحْبَبْتُ أَنْ أَمُوتَ وَأَنَا مَمْلُوكٌ ‏","","",""],[8023,8023,"","আমরা যেভাবে একজন ভালো শিকারী হয়ে উঠি, সেই বিষয়ে আমরা কথা বলেছিলাম, যখন আমরা তা শুনতে শুরু করেছিলাম । তাদের আগমন এবং তাদের ভাগ্য তাদের ভাগ্যে তারা আপনার আশীর্বাদ করবে এবং আমি আপনার আছে আছে আছে আছে আছে, আমি আপনাকে যা করতে বলছি, আমি যাচ্ছি, আমি চাই আপনি যা করছি তাই করুন। ঈশ্বর কীভাবে লবণকে জলে যেতে হবে, সেই বিষয়ে ঈশ্বর সন্দেহ করেন ।","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ اللَّهِ الْقَرَّاظُ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏سَعْدَ بْنَ مَالِكٍ ‏ ‏وَأَبَا هُرَيْرَةَ ‏ ‏يَقُولَانِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ بَارِكْ لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏فِي مَدِينَتِهِمْ وَبَارِكْ لَهُمْ فِي ‏ ‏صَاعِهِمْ ‏ ‏وَبَارِكْ لَهُمْ فِي ‏ ‏مُدِّهِمْ ‏ ‏اللَّهُمَّ إِنَّ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَبْدُكَ وَخَلِيلُكَ وَإِنِّي عَبْدُكَ وَرَسُولُكَ وَإِنَّ ‏ ‏إِبْرَاهِيمَ ‏ ‏سَأَلَكَ لِأَهْلِ ‏ ‏مَكَّةَ ‏ ‏وَإِنِّي أَسْأَلُكَ لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏كَمَا سَأَلَكَ ‏ ‏إِبْرَاهِيمُ ‏ ‏لِأَهْلِ ‏ ‏مَكَّةَ ‏ ‏وَمِثْلَهُ مَعَهُ إِنَّ ‏ ‏الْمَدِينَةَ ‏ ‏مُشْتَبِكَةٌ بِالْمَلَائِكَةِ عَلَى كُلِّ ‏ ‏نَقْبٍ ‏ ‏مِنْهَا مَلَكَانِ يَحْرُسَانِهَا لَا يَدْخُلُهَا الطَّاعُونُ وَلَا ‏ ‏الدَّجَّالُ ‏ ‏فَمَنْ أَرَادَهَا بِسُوءٍ أَذَابَهُ اللَّهُ كَمَا يَذُوبُ الْمِلْحُ فِي الْمَاءِ ‏","","",""],[8024,8024,"","আমরা সেই দিনের বাবার সঙ্গে কথা বলেছিলাম, যখন আমরা আমার বাবার কাছে একজন জিনিয়াস ছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ يَعْنِي الرَّازِيَّ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُصَلِّيَ أَحَدُنَا مُخْتَصِرًا ‏","","",""],[8025,8025,"","তিনি আপনার আত্মার পশম পূরণ করতে বলেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَأَنْ يَمْتَلِئَ جَوْفُ أَحَدِكُمْ قَيْحًا خَيْرٌ لَهُ مِنْ أَنْ يَمْتَلِئَ شِعْرًا ‏","","",""],[8026,8026,"","সেই সাহিত্যাদি বলেছিল যে, আমার বাবা ও রোরো দুই বছর বয়সী একজন পলাতক ব্যক্তি, যিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন । তার কাছে প্রার্থনা করো যে সে শয়তানের কাছে আত্মসমর্পণ করবে যে তাকে ধ্বংস করবে। আর তার অনুগ্রহ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ يَعْنِي الْمُؤَدِّبَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَاسْمُهُ ‏ ‏مُحَمَّدُ بْنُ مُسْلِمِ بْنِ أَبِي الْوَضَّاحِ أَبُو سَعِيدٍ الْمُؤَدِّبِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَرَوَى عَنْهُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏وَأَبُو دَاوُدَ ‏ ‏وَأَبُو كَامِلٍ ‏ ‏قَالَ ثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الشَّيْطَانَ يَأْتِي أَحَدَكُمْ فَيَقُولُ مَنْ خَلَقَ السَّمَاءَ فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ فَيَقُولُ مَنْ خَلَقَ الْأَرْضَ فَيَقُولُ اللَّهُ فَيَقُولُ مَنْ خَلَقَ اللَّهَ فَإِذَا أَحَسَّ أَحَدُكُمْ بِشَيْءٍ مِنْ هَذَا فَلْيَقُلْ آمَنْتُ بِاللَّهِ وَبِرُسُلِهِ ‏","","",""],[8027,8027,"","আমরা বাবার সাথে আমার বাবার সম্পর্কে কথা বলেছিলাম... ...আমার বাবাকে নগ্ন হওয়ার ব্যাপারে, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তিনি আতঙ্কের মধ্যে ছিলেন.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَقِيلٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَيَّانَ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ الذِّرَاعَ ‏","","",""],[8028,8028,"","বাবা আমাকে গ্রেফতার করার সময় আমার বাবাকে মেরে ফেলার কথা বলেছিলাম। আমার বাবা হয়তো তার নাম মেরে ফেলতে পারেন। আমার বাবা খুশি হবেন যে, ঈশ্বর তার ও তোমার জন্য প্রার্থনা করেছেন। লর্ড আপনার কাছে কখনো আসেনি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَقِيلٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏اسْمُهُ ‏ ‏عَبْدُ اللَّهِ بْنُ عَقِيلٍ الثَّقَفِيُّ ‏ ‏ثِقَةٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمِينُكَ مَا يُصَدِّقُكَ بِهِ صَاحِبُكَ ‏","","",""],[8029,8029,"","আমার বাবা একজন পলাতক ছিলেন আর তিনি আক্রমণের পর প্রার্থনা করবেন না ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏وَرْقَاءُ بْنُ عُمَرَ الْيَشْكُرِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ دِينَارٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا صَلَاةَ بَعْدَ الْإِقَامَةِ إِلَّا الْمَكْتُوبَةَ ‏","","",""],[8030,8030,"","একটা ঘোড়া বলেছিল যে, আমি ভাববাদীর কাছে প্রার্থনা করেছিলাম এবং দেরানের প্রাচীরের ভিতরে রাখা হয়েছিল । আমি তার কথা মনে করে তাকে বলেছিলাম যে, আমার চেয়ে ভাল হওয়ার পর তিনি তার সঙ্গে সময় কাটাবেন । ঈশ্বর তার কাছে প্রার্থনা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي يَزِيدَ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سُوقٍ مِنْ أَسْوَاقِ ‏ ‏الْمَدِينَةِ ‏ ‏فَانْصَرَفَ وَانْصَرَفْتُ مَعَهُ فَجَاءَ إِلَى فِنَاءِ ‏ ‏فَاطِمَةَ ‏ ‏فَنَادَى ‏ ‏الْحَسَنَ ‏ ‏فَقَالَ أَيْ ‏ ‏لُكَعُ ‏ ‏أَيْ ‏ ‏لُكَعُ ‏ ‏أَيْ ‏ ‏لُكَعُ ‏ ‏قَالَهُ ثَلَاثَ مَرَّاتٍ فَلَمْ يُجِبْهُ أَحَدٌ قَالَ فَانْصَرَفَ وَانْصَرَفْتُ مَعَهُ قَالَ فَجَاءَ إِلَى فِنَاءِ ‏ ‏عَائِشَةَ ‏ ‏فَقَعَدَ قَالَ فَجَاءَ ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏ظَنَنْتُ أَنَّ أُمَّهُ حَبَسَتْهُ لِتَجْعَلَ فِي عُنُقِهِ ‏ ‏السِّخَابَ ‏ ‏فَلَمَّا جَاءَ الْتَزَمَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْتَزَمَ هُوَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ إِنِّي أُحِبُّهُ فَأَحِبَّهُ وَأَحِبَّ مَنْ يُحِبُّهُ ثَلَاثَ مَرَّاتٍ ‏","","",""],[8031,8031,"","তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন এবং তার ভাগ্যের পর যাকে তিনি বিশ্বাস করতেন, তার কাছে আত্মসমর্পণ করেছিলেন । ঠিক আছে, তারপর সে তাকে তার কাছে নিয়ে যায়, কারণ সে আমাকে চ্যালেঞ্জ করে তাকে চ্যালেঞ্জ করে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏قَالَا ثَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَصَدَّقَ بِعَدْلِ تَمْرَةٍ مِنْ كَسْبٍ طَيِّبٍ وَلَا يَصْعَدُ إِلَى اللَّهِ إِلَّا الطَّيِّبُ فَإِنَّ اللَّهَ يَقْبَلُهَا بِيَمِينِهِ ثُمَّ ‏ ‏يُرَبِّيهَا لِصَاحِبِهَا كَمَا يُرَبِّي أَحَدُكُمْ ‏ ‏فَلُوَّهُ ‏ ‏حَتَّى تَكُونَ مِثْلَ الْجَبَلِ ‏","","",""],[8032,8032,"","আমরা বাবার সাথে আমার বাবার কথা বলেছি, ঈশ্বর তাকে জিজ্ঞেস করেছেন আর বলবে সে তাকে অপরাধী ছেড়ে দেবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَدْخُلُ الْجَنَّةَ أَقْوَامٌ أَفْئِدَتُهُمْ مِثْلُ أَفْئِدَةِ الطَّيْرِ ‏","","",""],[8033,8033,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি বলেন যে, ঈশ্বর হলেন সেই উত্তর, যা আমি কখনো জানি না । মনে আছে, তার হাতের মালিক হওয়ার কথা, আমি তাদের হারিয়ে ফেলেছি যেন আমি উড়ন্ত দার্শনিক।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَاه ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَهُوَ الصَّوَابُ ‏ ‏يَعْنِي لَمْ يَذْكُرْ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَدْخُلُ الْجَنَّةَ أَقْوَامٌ أَفْئِدَتُهُمْ مِثْلُ أَفْئِدَةِ الطَّيْرِ ‏","","",""],[8034,8034,"","আমি আমার বাবার সম্বন্ধে একটা কালো ছেলেদের সম্বন্ধে কথা বলেছিলাম, যাদের সম্বন্ধে আমি আমার বাবা একজন উৎপীড়ক ছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَمَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِثَلَاثٍ ‏ ‏بِنَوْمٍ عَلَى ‏ ‏وِتْرٍ ‏ ‏وَالْغُسْلِ يَوْمَ الْجُمُعَةِ وَصَوْمِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ ‏","","",""],[8035,8035,"","আমি আমার ছেলেকে খুঁজে পেতে সাহায্য করার চেষ্টা করেছিলাম । ( আদিপুস্তক ৬: ১ - ৩) তাঁর ইচ্ছার সবচেয়ে ভাল দিক, তিনি যখন ঈশ্বরকে বলেছিলেন, তখন তিনি সম্মানিত হয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُرِيدُ سَفَرًا لِيُوَدِّعَهُ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُوصِيكَ بِتَقْوَى اللَّهِ وَالتَّكْبِيرِ عَلَى كُلِّ شَرَفٍ فَلَمَّا وَلَّى قَالَ اللَّهُمَّ اطْوِ لَهُ الْبَعِيدَ وَهَوِّنْ عَلَيْهِ السَّفَرَ ‏","","",""],[8036,8036,"","আমরা আমার বাবা কুমারী হওয়ার কথা বলেছিলাম। তুমি একটা কোদাল লিখলে আর তারা জানে না যে, সে তোমাকে ছেড়ে চলে যেতে হবে কিনা। শিকারী বলেছে তুমি অন্ধকারে ছিলে আর আল্লাহ্‌র অদ্ভুত স্টান্ট ( গীতসংহিতা ৩৭: ১১) আর তাঁর ইচ্ছা কখনোই অন্ধকারে থাকবে না ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ كَانَ يَقُولُ كَيْفَ أَنْتُمْ إِذَا لَمْ تَجْتَبُوا دِينَارًا وَلَا دِرْهَمًا فَقِيلَ لَهُ وَهَلْ ‏ ‏تَرَى ذَلِكَ كَائِنًا يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَقَالَ وَالَّذِي نَفْسُ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏بِيَدِهِ عَنْ قَوْلِ ‏ ‏الصَّادِقِ الْمَصْدُوقِ ‏ ‏قَالُوا وَعَمَّ ذَاكَ قَالَ ‏ ‏تُنْتَهَكُ ذِمَّةُ اللَّهِ وَذِمَّةُ رَسُولِهِ فَيَشُدُّ اللَّهُ قُلُوبَ أَهْلِ الذِّمَّةِ فَيَمْنَعُونَ مَا بِأَيْدِيهِمْ ‏ ‏وَالَّذِي نَفْسُ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏بِيَدِهِ لَيَكُونَنَّ مَرَّتَيْنِ ‏","","",""],[8037,8037,"","আমার বাবা এমন একজন ব্যক্তি ছিলেন, যিনি তার কাছে প্রার্থনা করেছেন এবং বলবেন যে, তিনি একজন পুরুষ । আর একজন লোক এমন একজন লোক যাকে বলা হয়েছে যে একজন মানুষ হিসেবে সে একজন পুরুষ ও নারী ব ্ যতীত আর কোনো একজন পুরুষই পুরুষ । আর যে মানুষ আছে পুরুষ ও নারী , সে ব ্ যর ্ থভাবে যার কাছে একজন মানুষ চায় , তাহলে তার সঙ ্ গেই গেছে একজন লোক , -- আর যে মানুষ আছে পুরুষ ও নারী , সে ব ্ যর ্ থভাবে যার কাছে আল ্ লাহ ্ ‌ র তরফ থেকে জ ্ ঞান এসেছে , সে ব ্ যক ্ তি যে আছে তার গ ্ রন ্ থভাবে । যে লোক পুরুষ ও নারী আছে , তার জন ্ যে সে একজন মানুষ বৈ নয় । এমন একজন মানুষ আছে যার কাছে এমন একজন মানুষ আছে যে তার মনের ভেতর থেকে পালিয়ে যাওয়ার চেষ্টা করে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ شَاذَانُ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَ رَجُلٌ يُدَايِنُ النَّاسَ قَالَ وَكَانَ يَقُولُ لِفَتَاهُ إِذَا أَتَيْتَ مُعْسِرًا فَتَجَاوَزْ عَنْهُ لَعَلَّ اللَّهَ يَتَجَاوَزُ عَنَّا فَلَقِيَ اللَّهَ فَتَجَاوَزَ عَنْهُ ‏","","",""],[8038,8038,"","আমি আমার বাবার কথা বলেছিলাম আমার ভাইকে বলা কথা, সে এখন বেঁচে যাবে, ১০০ ঘন্টাও কম থাকবে না, তুমি হবে, যদি আমি তাকে হত্যা না করি।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَحْسِرُ الْفُرَاتُ ‏ ‏أَوْ لَا تَقُومُ السَّاعَةُ حَتَّى يَحْسِرَ الْفُرَاتُ ‏ ‏عَنْ جَبَلٍ مِنْ ذَهَبٍ فَيَقْتَتِلَ عَلَيْهِ النَّاسُ فَيُقْتَلَ مِنْ كُلِّ مِائَةٍ تِسْعَةٌ وَتِسْعُونَ يَا بُنَيَّ فَإِنْ أَدْرَكْتَهُ فَلَا تَكُونَنَّ مِمَّنْ يُقَاتِلُ عَلَيْهِ ‏","","",""],[8039,8039,"","আমার দক্ষতাটা সম্পন্ন করা উচিত, ঈশ্বরের ইচ্ছা আছে, এটা হলো কাটাচোরের কারণে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ الْفَضْلِ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنِي ‏ ‏مُعَاوِيَةَ الْمَهْرِيُّ ‏ ‏قَالَ قَالَ ‏ ‏لِي ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يَا ‏ ‏مَهْرِيُّ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ثَمَنِ الْكَلْبِ ‏ ‏وَكَسْبِ الْحَجَّامِ ‏ ‏وَكَسْبِ ‏ ‏الْمُومِسَةِ ‏ ‏وَعَنْ كَسْبِ ‏ ‏عَسْبِ ‏ ‏الْفَحْلِ ‏","","",""],[8040,8040,"","আমি আমার বাবাকে একজন উৎপীড়ক বলে মনে করতাম ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُنْزِلَ الْقُرْآنُ عَلَى سَبْعَةِ أَحْرُفٍ عَلِيمًا حَكِيمًا غَفُورًا رَحِيمًا ‏","","",""],[8041,8041,"","আমার বাবা একজন উৎপীড়ক ছিলেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْكَرِيمَ ابْنَ الْكَرِيمِ ابْنِ الْكَرِيمِ ابْنِ الْكَرِيمِ ‏ ‏يُوسُفُ بْنُ يَعْقُوبَ بْنِ إِسْحَاقَ بَنِ إِبْرَاهِيمَ خَلِيلِ الرَّحْمَنِ ‏ ‏عَزَّ وَجَلَّ ‏","","",""],[8042,8042,"","তিনি বলেছিলেন, ঈশ্বর যদি আমাকে জেলে না নিয়ে যান, তাহলে তিনি জেলে যেতে পারতেন, প্রভু আমাকে মেরে ফেলতেন। নিজের নিয়ন্ত্রণ করতে হবে, তার শক্তির ভবিষ্যতবাণী থেকে.","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ لَبِثْتُ فِي السِّجْنِ مَا لَبِثَ ‏ ‏يُوسُفُ ‏ ‏ثُمَّ جَاءَنِي الدَّاعِي لَأَجَبْتُهُ إِذْ جَاءَهُ الرَّسُولُ فَقَالَ ‏ { ‏ارْجِعْ إِلَى رَبِّكَ فَاسْأَلْهُ مَا بَالُ النِّسْوَةِ اللَّاتِي قَطَّعْنَ أَيْدِيَهُنَّ إِنَّ رَبِّي بِكَيْدِهِنَّ عَلِيمٌ ‏} ‏وَرَحْمَةُ اللَّهِ عَلَى ‏ ‏لُوطٍ ‏ ‏إِنْ كَانَ لَيَأْوِي إِلَى رُكْنٍ شَدِيدٍ إِذْ قَالَ لِقَوْمِهِ ‏ { ‏لَوْ أَنَّ لِي بِكُمْ قُوَّةً أَوْ آوِي إِلَى رُكْنٍ شَدِيدٍ ‏} ‏وَمَا بَعَثَ اللَّهُ مِنْ بَعْدِهِ مِنْ نَبِيٍّ إِلَّا فِي ثَرْوَةٍ مِنْ قَوْمِهِ ‏","","",""],[8043,8043,"","ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং তিনি আরও ভাল হতে ও উড়তে পছন্দ করবেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ الْفَأْلَ الْحَسَنَ وَيَكْرَهُ ‏ ‏الطِّيَرَةَ ‏","","",""],[8044,8044,"","আমার ভাই হাররার সম্পর্কে একটা স্বপ্নের কথা বলেছিলাম, যখন আমরা তোমার সাথে খারাপ ব্যবহার করি, তখন তাকে আমি অগ্নিসংযোগ করতে শুরু করি,","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا أَنَا بَشَرٌ وَلَعَلَّ بَعْضَكُمْ أَنْ يَكُونَ أَلْحَنَ بِحُجَّتِهِ مِنْ بَعْضٍ فَمَنْ قَطَعْتُ لَهُ مِنْ حَقِّ أَخِيهِ قِطْعَةً فَإِنَّمَا أَقْطَعُ لَهُ قِطْعَةً مِنْ النَّارِ ‏","","",""],[8045,8045,"","আমার বাবা যখন একজন দেবতা ছিলেন, তখন আমরা এক নির্দিষ্ট মন্দের সঙ্গে কথা বলেছিলাম । মানুষ আর রক্ষক আমাকে বলত যে সে তোমাকে অনেক দূর নিয়ে গেছে, আমি শুধু তাকেই দেখব.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏دَخَلَ أَعْرَابِيٌّ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ أَخَذَتْكَ أُمُّ مِلْدَمٍ قَطُّ قَالَ وَمَا أُمُّ مِلْدَمٍ قَالَ حَرٌّ يَكُونُ بَيْنَ الْجِلْدِ وَاللَّحْمِ قَالَ مَا وَجَدْتُ هَذَا قَطُّ قَالَ فَهَلْ أَخَذَكَ هَذَا الصُّدَاعُ قَطُّ قَالَ وَمَا هَذَا الصُّدَاعُ قَالَ عِرْقٌ يَضْرِبُ عَلَى الْإِنْسَانِ فِي رَأْسِهِ قَالَ مَا وَجَدْتُ هَذَا قَطُّ فَلَمَّا وَلَّى قَالَ مَنْ أَحَبَّ أَنْ يَنْظُرَ إِلَى رَجُلٍ مِنْ أَهْلِ النَّارِ فَلْيَنْظُرْ إِلَى هَذَا ‏","","",""],[8046,8046,"","আর সে আমার বাবাকে ফোন করছে, একজন রাজকুমারী যে ঈশ্বরকে ঈশ্বরের কাছে প্রার্থনা করতে বলেছিল, তার শান্তি আছে আর তাকে আমার ছেড়ে দিতে হবে। তিন আর দুই সপ্তাহ দূরে।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏افْتَرَقَتْ ‏ ‏الْيَهُودُ ‏ ‏عَلَى إِحْدَى ‏ ‏أَوْ اثْنَتَيْنِ ‏ ‏وَسَبْعِينَ فِرْقَةً وَتَفْتَرِقُ أُمَّتِي عَلَى ثَلَاثٍ وَسَبْعِينَ فِرْقَةً ‏","","",""],[8047,8047,"","আর সে আমার বাবাকে ফোন করছে, যে কিনা ঈশ্বরের কাছে বলছে যে সে তার প্রভুর কাছে এসেছে এবং তার পঞ্চম জন পবিত্র আত্মার কাছে পৌঁছে দিয়েছে। আদালত আবার আদালতে বিচার করে।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَمْسٌ مِنْ حَقِّ الْمُسْلِمِ عَلَى الْمُسْلِمِ رَدُّ التَّحِيَّةِ وَإِجَابَةُ الدَّعْوَةِ وَشُهُودُ الْجِنَازَةِ وَعِيَادَةُ الْمَرِيضِ ‏ ‏وَتَشْمِيتُ ‏ ‏الْعَاطِسِ إِذَا حَمِدَ اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[8048,8048,"","এবং তিনি আমার বাবাকে ফোন করেছেন, একজন ভালো মানুষ বলেছিলেন যে তার শান্তি আর আত্মসমর্পন করার জন্য ঈশ্বরের কাছে প্রার্থনা করবে। গ্যাব্রিয়েল তার দিকে তাকিয়ে বললেন, আমি তাকে যা করতে চাই, তা তার দিকে তাকিয়ে আছি। আমি তাকে যেতে দেব না, সে বলেছিল, সে হয়তো তার মন পছন্দ করেছে। তার দিকে তাকাও, আমি প্রতিজ্ঞা করছি, আমি কিছু কাজ করব, বরং আমি যা করব, তা করব। আমি ভয় পেয়েছিলাম যে, তিনি আর কখনো বেঁচে যাবেন না ।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا خَلَقَ اللَّهُ الْجَنَّةَ وَالنَّارَ أَرْسَلَ ‏ ‏جِبْرِيلَ ‏ ‏قَالَ ‏ ‏انْظُرْ إِلَيْهَا وَإِلَى مَا أَعْدَدْتُ لِأَهْلِهَا فِيهَا فَجَاءَ فَنَظَرَ إِلَيْهَا وَإِلَى مَا أَعَدَّ اللَّهُ لِأَهْلِهَا فِيهَا فَرَجَعَ إِلَيْهِ قَالَ وَعِزَّتِكَ لَا يَسْمَعُ بِهَا أَحَدٌ إِلَّا دَخَلَهَا فَأَمَرَ بِهَا فَحُجِبَتْ بِالْمَكَارِهِ قَالَ ارْجِعْ إِلَيْهَا فَانْظُرْ إِلَيْهَا وَإِلَى مَا أَعْدَدْتُ لِأَهْلِهَا فِيهَا قَالَ فَرَجَعَ إِلَيْهَا وَإِذَا هِيَ قَدْ حُجِبَتْ بِالْمَكَارِهِ فَرَجَعَ إِلَيْهِ قَالَ وَعِزَّتِكَ قَدْ خَشِيتُ أَنْ لَا يَدْخُلَهَا أَحَدٌ قَالَ اذْهَبْ إِلَى النَّارِ فَانْظُرْ إِلَيْهَا وَإِلَى مَا أَعْدَدْتُ لِأَهْلِهَا فِيهَا فَإِذَا هِيَ يَرْكَبُ بَعْضُهَا بَعْضًا فَرَجَعَ قَالَ وَعِزَّتِكَ لَقَدْ خَشِيتُ أَنْ لَا يَسْمَعَ بِهَا أَحَدٌ فَيَدْخُلَهَا فَأَمَرَ بِهَا فَحُفَّتْ بِالشَّهَوَاتِ فَقَالَ وَعِزَّتِكَ لَقَدْ خَشِيتُ أَنْ لَا يَنْجُوَ مِنْهَا أَحَدٌ إِلَّا دَخَلَهَا ‏","","",""],[8049,8049,"","আর আমার বাবাকে ফোন করে, আমার ছেলের সাথে শান্তি ছিল। আমি তাদের একজনকে দেখতে পাবো। ঈশ্বর, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে ঈশ্বরের কাছে । ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে ঈশ্বরের কাছে, ঈশ্বরের কাছে ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে ঈশ্বরের কাছে, ঈশ্বরের কাছে ঈশ্বরের কাছে । ঈশ্বরের অনুগ্রহে আশ্বস্ত কর, সে তাকে কি ভাবে উদ্ধার করতে হয় তা শিক্ষা দিয়েছে। আমার ছেলে আমাকে বলছে, আমার ছেলে আমার চেয়ে কতটা বয়স্ক। ঈশ্বরই তো সেই মানুষ যে আমার নিজের মাটির নিচে থেকে বেঁচে আছে.","‏ ‏وَبِإِسْنَادِهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَجُلَانِ مِنْ ‏ ‏بَلِيٍّ ‏ ‏مِنْ ‏ ‏قُضَاعَةَ ‏ ‏أَسْلَمَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاسْتُشْهِدَ أَحَدُهُمَا وَأُخِّرَ الْآخَرُ سَنَةً قَالَ ‏ ‏طَلْحَةُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏فَأُرِيتُ الْجَنَّةَ فَرَأَيْتُ فِيهَا الْمُؤَخَّرَ مِنْهُمَا أُدْخِلَ قَبْلَ الشَّهِيدِ فَعَجِبْتُ لِذَلِكَ فَأَصْبَحْتُ فَذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ ذُكِرَ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَيْسَ قَدْ صَامَ بَعْدَهُ رَمَضَانَ وَصَلَّى سِتَّةَ آلَافِ رَكْعَةٍ ‏ ‏أَوْ كَذَا وَكَذَا رَكْعَةً ‏ ‏صَلَاةَ السَّنَةِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ يَعْنِي ابْنَ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏أَنَّ رَجُلَيْنِ مِنْ ‏ ‏بَلِيٍّ ‏ ‏وَهُمْ حَيٌّ مِنْ ‏ ‏قُضَاعَةَ ‏ ‏فَذَكَرَهُ ‏","","",""],[8050,8050,"","আমরা আবেগ নিয়ে কথা বলেছি যে আমরা জমজজে গেছি আর স্বপ্ন দেখতে যাচ্ছি, কিছু মানুষ দেখা গেছে আর দেখা যাচ্ছে চলে যাচ্ছে, আমি বলবো আমার বাবা। ঈশ্বর তার অনুগ্রহের জন্য ঈশ্বরকে প্রার্থনা করেছেন এবং ঈশ্বর তাকে যেতে নিষেধ করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏حَدَّثَنِي ‏ ‏وَهْبُ بْنُ كَيْسَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْأَزْرَقِ ‏ ‏قَالَ ‏ ‏تُوُفِّيَ بَعْضُ ‏ ‏كَنَائِنِ ‏ ‏مَرْوَانَ ‏ ‏فَشَهِدَهَا النَّاسُ وَشَهِدَهَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَمَعَهَا نِسَاءٌ يَبْكِينَ فَأَمَرَهُنَّ ‏ ‏مَرْوَانُ ‏ ‏فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏دَعْهُنَّ فَإِنَّهُ مَرَّ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَنَازَةٌ مَعَهَا ‏ ‏بَوَاكٍ ‏ ‏فَنَهَرَهُنَّ ‏ ‏عُمَرُ ‏ ‏رَحِمَهُ اللَّهُ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعْهُنَّ فَإِنَّ النَّفْسَ مُصَابَةٌ وَالْعَيْنَ دَامِعَةٌ وَالْعَهْدَ حَدِيثٌ ‏","","",""],[8051,8051,"","আমরা তোমার মাংসের আবরণ দিয়ে তৈরি একটা অশুভের কথা বলেছি, একটা নিয়মিক ওয়ার্ডের সামনে সে বলল আমরা তোমার বাসাকে নিচু করে না দেখে তোমার বাসাকে লক্ষ্য করি আমি তার সাথে কিভাবে কাজ করব সেটা আমি কিভাবে করবো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ ‏} ‏جَعَلَ يَدْعُو بُطُونَ ‏ ‏قُرَيْشٍ ‏ ‏بَطْنًا بَطْنًا يَا بَنِي فُلَانٍ ‏ ‏أَنْقِذُوا أَنْفُسَكُمْ مِنْ النَّارِ حَتَّى انْتَهَى إِلَى ‏ ‏فَاطِمَةَ ‏ ‏فَقَالَ يَا ‏ ‏فَاطِمَةُ ابْنَةَ مُحَمَّدٍ ‏ ‏أَنْقِذِي نَفْسَكِ مِنْ النَّارِ لَا أَمْلِكُ لَكُمْ مِنْ اللَّهِ شَيْئًا غَيْرَ أَنَّ لَكُمْ رَحِمًا ‏ ‏سَأَبُلُّهَا ‏ ‏بِبَلَالِهَا ‏","","",""],[8052,8052,"","আমরা আমার বাবার সাথে কথা বলেছিলাম যে আমার বাবা একজন উন্মাদ ছিলেন. আজ রাতে তাকে নিজের কাজ করতে হবে. আমি কখনো ঈশ্বরকে দেখিনি, আমি মাটির সাথে আছি, হয় রাতে বা দিনে, আমার ছেলের রান্নার সময় নয়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَيَّانَ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِبِلَالٍ ‏ ‏عِنْدَ صَلَاةِ الْفَجْرِ يَا ‏ ‏بِلَالُ ‏ ‏خَبِّرْنِي بِأَرْجَى عَمَلٍ عَمِلْتَهُ مَنْفَعَةً فِي الْإِسْلَامِ فَإِنِّي قَدْ ‏ ‏سَمِعْتُ اللَّيْلَةَ ‏ ‏خَشْفَ ‏ ‏نَعْلَيْكَ بَيْنَ يَدَيَّ فِي الْجَنَّةِ قَالَ مَا عَمِلْتُ يَا رَسُولَ اللَّهِ فِي الْإِسْلَامِ عَمَلًا أَرْجَى عِنْدِي مَنْفَعَةً مِنْ أَنِّي لَمْ أَتَطَهَّرْ طُهُورًا تَامًّا قَطُّ فِي سَاعَةٍ مِنْ لَيْلٍ أَوْ نَهَارٍ إِلَّا صَلَّيْتُ بِذَلِكَ الطُّهُورِ لِرَبِّي مَا كُتِبَ لِي أَنْ أُصَلِّيَ ‏","","",""],[8053,8053,"","আমরা একটি ছেলেকে নতুন করে নতুন করে আবিষ্কার করার চেষ্টা করেছি, যে আমাকে সাহায্য করতে হবে। ভবিষ্যদ্বাণীর এক উপহার তার কাছে প্রার্থনা করেছে এবং যাকে আমি পাপ করেছি তাকে উদ্ধার করা হবে। আমরা অনেক কিছু জানি, আমরা এই ব্যাপারে কথা বলেছি। আমরা কিভাবে ভাল কাজ করার চেয়ে ভাল কাজ করেছি.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَزِيدَ بْنِ عَبْدِ الْمَلِكِ يَعْنِي النَّوْفَلِيَّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏ذَكَرَهُ عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَفْضَى بِيَدِهِ إِلَى ذَكَرِهِ لَيْسَ دُونَهُ سِتْرٌ فَقَدْ وَجَبَ عَلَيْهِ الْوُضُوءُ ‏ ‏حَدَّثَنَا ‏ ‏الْهَيْثَمُ بْنُ خَارِجَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَزِيدَ بْنِ عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[8054,8054,"","আমরা এমন এক ছেলে হতে যাচ্ছি, যে আমার বাবাকে মুক্ত বিশ্বাস করতে পারে। ঈশ্বর বলে দিয়েছেন যদি আমরা শক্তিশালী না হই তাহলে তার চেয়েও বেশি কিছু বলবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَزِيدَ بْنِ عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَكْثِرُوا مِنْ قَوْلِ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ فَإِنَّهَا كَنْزٌ مِنْ كُنُوزِ الْجَنَّةِ ‏","","",""],[8055,8055,"","আমি যখন তাকে বলেছিলাম যে, আমি একজন যিহোবার সাক্ষি ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ أَبِي صَالِحٍ ‏ ‏وَكَانَ يُقَالُ لَهُ ‏ ‏ابْنُ نُفَيْلَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ثَمَنُ ‏ ‏الْجَرِيسَةِ ‏ ‏حَرَامٌ وَأَكْلُهَا حَرَامٌ ‏","","",""],[8056,8056,"","আমরা আমার বাবার সাথে কুঁড়েঘ্যান নিয়ে কথা বলেছি আর তাকে আমার ভালবাসার কথা বলেছিলাম, সে তাদের দিয়ে দেবে, নাহলে তারা গুলি করবে.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏وَأُرَاهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَنْتَهِيَنَّ أَقْوَامٌ يَرْفَعُونَ أَبْصَارَهُمْ إِلَى السَّمَاءِ فِي الصَّلَاةِ أَوْ لَتُخْطَفَنَّ أَبْصَارُهُمْ ‏","","",""],[8057,8057,"","আমরা আমার বাবা একজন উৎপীড়ক ছিলেন যে তোমাকে শুনেছি যে সে তোমাকে বলেছে সে কিছু বলবে না যে তার কথা বা কথা যা কিছু বলে আমার বাবা একজন পলাতক যে বলেছে আমি একজন দেবতা, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর সে আত্মসমর্পণ করবে আর আমি তোমাকে বলেছি আমি আমার হৃদয়ের গভীরে ঢুকিয়ে দেব যদি আমি একজন মানুষকে খুঁজে পেতাম এমন একজন মানুষ যে হবে যে হবে পৃথিবীর মানুষ, সে হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَلَا مِنْ رَجُلٍ يَأْخُذُ بِمَا فَرَضَ اللَّهُ وَرَسُولُهُ كَلِمَةً أَوْ كَلِمَتَيْنِ أَوْ ثَلَاثًا أَوْ أَرْبَعًا أَوْ خَمْسًا فَيَجْعَلُهُنَّ فِي طَرَفِ رِدَائِهِ فَيَتَعَلَّمُهُنَّ وَيُعَلِّمُهُنَّ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَقُلْتُ أَنَا يَا رَسُولَ اللَّهِ قَالَ فَابْسُطْ ثَوْبَكَ قَالَ فَبَسَطْتُ ثَوْبِي فَحَدَّثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ ضُمَّ إِلَيْكَ فَضَمَمْتُ ثَوْبِي إِلَى صَدْرِي ‏ ‏فَإِنِّي لَأَرْجُو أَنْ لَا أَكُونَ نَسِيتُ حَدِيثًا سَمِعْتُهُ مِنْهُ بَعْدُ ‏","","",""],[8058,8058,"","আমরা যে দিন ঈশ্বরের সর্বোচ্চ কথা বলেছিলাম, সে ছিল আমার বাবা তার নিজের রক্তপাতের জন্য ঈশ্বরকে অনুরোধ করার জন্য উপহার। আর সে আগুনের বাইরে চলে গেছে, আর তা আর এখনো দেখা যায়নি। যা পারে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضِرْسُ الْكَافِرِ مِثْلُ ‏ ‏أُحُدٍ ‏ ‏وَفَخِذُهُ مِثْلُ ‏ ‏الْبَيْضَاءِ ‏ ‏وَمَقْعَدُهُ مِنْ النَّارِ كَمَا بَيْنَ ‏ ‏قُدَيْدٍ ‏ ‏وَمَكَّةَ ‏ ‏وَكَثَافَةُ جِلْدِهِ اثْنَانِ وَأَرْبَعُونَ ذِرَاعًا بِذِرَاعِ الْجَبَّارِ ‏","","",""],[8059,8059,"","আমি আমার বাবার কথা বলেছিলাম যে আমার ভাই ঈশ্বরের জন্য দেবতা হয়ে কথা বলছে তাকে ছেড়ে দিতে হবে লর্ডের সাথে কথা বলবে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْعَبْدَ لَيَتَكَلَّمُ بِالْكَلِمَةِ مِنْ رُضْوَانِ اللَّهِ عَزَّ وَجَلَّ لَا يُلْقِي لَهَا بَالًا يَرْفَعُهُ اللَّهُ بِهَا دَرَجَاتٍ وَإِنَّ الْعَبْدَ لَيَتَكَلَّمُ بِالْكَلِمَةِ مِنْ سَخَطِ اللَّهِ لَا يُلْقِي لَهَا بَالًا يَهْوِي بِهَا فِي جَهَنَّمَ ‏","","",""],[8060,8060,"","আমি একজন দাস হিসেবে আমার হারের কথা বলেছিলাম, যিনি আমাকে একজন দাস হিসেবে সুখী বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ الْعَقَدِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمَّارٍ كَشَاكِشٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدًا الْمَقْبُرِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ الْكَسْبِ كَسْبُ يَدِ الْعَامِلِ إِذَا نَصَحَ ‏","","",""],[8061,8061,"","আমি বলেছিলাম যে, আমার মা মারা যাচ্ছে । তোমার সাথে একা একা থাকার আলো, আমরা জানি না কে তাকে বরখাস্ত করতে পারে, আমার বাবা একটা বিড়াল।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ عَبْدِ اللَّهِ الْمُجْمِرِ ‏ ‏أَنَّهُ رَقِيَ إِلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَلَى ظَهْرِ الْمَسْجِدِ وَهُوَ يَتَوَضَّأُ فَرَفَعَ فِي عَضُدَيْهِ ثُمَّ أَقْبَلَ عَلَيَّ فَقَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أُمَّتِي يَوْمَ الْقِيَامَةِ هُمْ ‏ ‏الْغُرُّ ‏ ‏الْمُحَجَّلُونَ ‏ ‏مِنْ آثَارِ الْوُضُوءِ فَمَنْ اسْتَطَاعَ مِنْكُمْ أَنْ يُطِيلَ ‏ ‏غُرَّتَهُ ‏ ‏فَلْيَفْعَلْ ‏ ‏فَقَالَ ‏ ‏نُعَيْمٌ ‏ ‏لَا أَدْرِي قَوْلُهُ مَنْ اسْتَطَاعَ أَنْ يُطِيلَ ‏ ‏غُرَّتَهُ ‏ ‏فَلْيَفْعَلْ مِنْ قَوْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ مِنْ قَوْلِ ‏ ‏أَبِي هُرَيْرَةَ ‏","","",""],[8062,8062,"","আমরা বাবার সাথে কথা বলেছি, আমরা ঈশ্বরের প্রেম নিয়ে কথা বলেছি, কিন্তু আমার ভাই মুক্ত, ঈশ্বর আপনাকে বলতে হবে কে বলেছে। আমার মায়ের ফক্স হচ্ছে সেই মৃত্যুর সে তার বছর থেকে এখানে আটকে থাকবে আর তার জীবনের সেরা পেশাদারিত্বের জন্য তাকে তার সেরা শিকার করা হবে। আগুন এবং বলা হয় ক্ষমার পর আমি বলতে চাচ্ছি যে, একজন ছেলে আটকে যাবে এবং সে বলবে যে, ঈশ্বর চাইলেই তাকে ভালবাসতে পারেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ تَدْرُونَ مَنْ الْمُفْلِسُ قَالُوا الْمُفْلِسُ فِينَا يَا رَسُولَ اللَّهِ مَنْ لَا لَهُ دِرْهَمَ وَلَا دِينَارَ وَلَا مَتَاعَ قَالَ ‏ ‏الْمُفْلِسُ مِنْ أُمَّتِي يَوْمَ الْقِيَامَةِ مَنْ يَأْتِي بِصَلَاةٍ وَصِيَامٍ وَزَكَاةٍ وَيَأْتِي قَدْ شَتَمَ عِرْضَ هَذَا وَقَذَفَ هَذَا وَأَكَلَ مَالَ هَذَا وَضَرَبَ هَذَا فَيُقْعَدُ ‏ ‏فَيَقْتَصُّ ‏ ‏هَذَا مِنْ حَسَنَاتِهِ وَهَذَا مِنْ حَسَنَاتِهِ فَإِنْ فَنِيَتْ حَسَنَاتُهُ قَبْلَ أَنْ ‏ ‏يُقْضَى مَا عَلَيْهِ أُخِذَ مِنْ خَطَايَاهُمْ فَطُرِحَ عَلَيْهِ ثُمَّ طُرِحَ فِي النَّارِ ‏ ‏و قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ مَهْدِيٍّ ‏ ‏فَيَقْتَصُّ وَقَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَبْلَ أَنْ ‏ ‏يُقْضَى مَا عَلَيْهِ ‏","","",""],[8063,8063,"","আমরা তার বাবার কথা বলেছিলাম আমার ভাই ভালো ছেলে হয়ে থাকলে সে আত্মসমর্পণ করবে যদি সে জানত যে সে ঐ ভ্রমণটা কখনো পবিত্রতা থেকে পড়ে নি আপনি যা করতে চাচ্ছেন, সেটা হলো তার নিজেরই একটা করুণা।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ يَعْلَمُ الْمُؤْمِنُ مَا عِنْدَ اللَّهِ مِنْ الْعُقُوبَةِ مَا طَمِعَ فِي الْجَنَّةِ أَحَدٌ وَلَوْ يَعْلَمُ الْكَافِرُ مَا عِنْدَ اللَّهِ مِنْ الرَّحْمَةِ مَا ‏ ‏قَنَطَ ‏ ‏مِنْ الْجَنَّةِ أَحَدٌ خَلَقَ اللَّهُ مِائَةَ رَحْمَةٍ فَوَضَعَ رَحْمَةً وَاحِدَةً بَيْنَ خَلْقِهِ يَتَرَاحَمُونَ بِهَا وَعِنْدَ اللَّهِ تِسْعَةٌ وَتِسْعُونَ رَحْمَةً ‏","","",""],[8064,8064,"","আমার বাবা বাবার ছেলের কাছে একটা বিয়ের আয়োজন করেছিলেন, বাবার ছেলের কাছে একজন দাস হিসেবে। ভালোবাসা থেকে শুরু করে ভালবাসা আর ভালবাসার গোপন বিষয় হতে যাচ্ছে, এটা কোন গল্পকে দুরে রাখতে পারে না, কিন্তু তাদের এটা খেলতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَسِيدِ بْنِ أَبِي أَسِيدٍ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ عَيَّاشٍ ‏ ‏مَوْلَى ‏ ‏عَقِيلَةَ بِنْتِ طَلْقٍ الْغِفَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَحَبَّ أَنْ يُطَوِّقَ حَبِيبَهُ طَوْقًا مِنْ نَارٍ فَلْيُطَوِّقْهُ طَوْقًا مِنْ ذَهَبٍ وَمَنْ أَحَبَّ أَنْ يُسَوِّرَ حَبِيبَهُ سِوَارًا مِنْ نَارٍ فَلْيُسَوِّرْهُ بِسِوَارٍ مِنْ ذَهَبٍ وَمَنْ أَحَبَّ أَنْ يُحَلِّقَ حَبِيبَهُ حَلْقَةً مِنْ نَارٍ فَلْيُحَلِّقْهُ حَلْقَةً مِنْ ذَهَبٍ وَلَكِنْ عَلَيْكُمْ بِالْفِضَّةِ الْعَبُوا بِهَا لَعِبًا الْعَبُوا بِهَا لَعِبًا ‏","","",""],[8065,8065,"","আমরা আমার বাবা একজন পলাতকের সাথে কথা বলেছিলাম, সে বলেছিল তুমি তার সম্পর্কে চিন্তা করবে.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنِي ‏ ‏مُوسَى بْنُ وَرْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَرْءُ عَلَى دِينِ ‏ ‏خَلِيلِهِ ‏ ‏فَلْيَنْظُرْ أَحَدُكُمْ مَنْ ‏ ‏يُخَالِلْ ‏","","",""],[8066,8066,"","আমি যখন ছোট ছিলাম, তখন আমি আমার ছেলেকে বলেছিলাম যে, আমি যদি একজন ছেলে হই, তা হলে আমি তাকে সাহায্য করতে পারব । কে সে?","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏وَسُرَيْجٌ ‏ ‏قَالَا ثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي عَمْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ ‏ ‏مُؤْمِنٍ إِلَّا وَأَنَا أَوْلَى بِهِ فِي الدُّنْيَا وَالْآخِرَةِ اقْرَءُوا إِنْ شِئْتُمْ ‏ { ‏النَّبِيُّ أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ ‏} ‏فَأَيُّمَا مُؤْمِنٍ هَلَكَ وَتَرَكَ مَالًا فَلْيَرِثْهُ ‏ ‏عَصَبَتُهُ ‏ ‏مَنْ كَانُوا وَمَنْ تَرَكَ دَيْنًا أَوْ ‏ ‏ضَيَاعًا ‏ ‏فَلْيَأْتِنِي فَإِنِّي مَوْلَاهُ ‏","","",""],[8067,8067,"","আমরা আমার ছেলে হিসেবে কতটা উত্তম বিষয়গুলো করেছি, সেই বিষয়ে আমরা কথা বলেছিলাম । হে ঈশ্বর, আমি তার প্রতিজ্ঞা করছি, ঈশ্বর তার জন্য কখনোই পারবে না। সে তার পথে আছে, যার মধ্যে সিঁড়ি সহ, ফ্রগ তাকে অনুরোধ করবে গুরুতর অপরাধ জয় করতে আর তোমার আত্মার সেবা করতে। বাবা, আমরা একটা ছেলে বা মেয়েকে দিয়ে দিয়েছি। বাবার ছেলের কথা কখনো জানে না একবার সে বলেছিল সে পালিয়ে যাচ্ছে। তাই সে বলেছিল সে একটা। আর তারপর আমরা তাকে বলবো, সে আমাকে একটা খারাপ কথা বলে। ছেলে, সে আমার বাবার কাছ থেকে দূরে যাবার জন্য আমাকে একটা ছেলে দিতে যাচ্ছে না, যে বলেছে ঈশ্বর তার জন্য প্রার্থনা করেছেন। সে তাকে উল্লেখ করেছে, সে সিংহাসনের কাছে পড়ে যাবে এবং সে তার মৃত্যুর হাত থেকে যাবে। অপরাধের নদী থেকে.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي عَمْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ آمَنَ بِاللَّهِ وَرَسُولِهِ وَأَقَامَ الصَّلَاةَ وَصَامَ رَمَضَانَ فَإِنَّ حَقًّا عَلَى اللَّهِ أَنْ يُدْخِلَهُ الْجَنَّةَ هَاجَرَ فِي سَبِيلِ اللَّهِ أَوْ جَلَسَ فِي أَرْضِهِ الَّتِي وُلِدَ فِيهَا قَالُوا يَا رَسُولَ اللَّهِ أَفَلَا نُخْبِرُ النَّاسَ قَالَ إِنَّ فِي الْجَنَّةِ مِائَةَ دَرَجَةٍ أَعَدَّهَا اللَّهُ عَزَّ وَجَلَّ لِلْمُجَاهِدِينَ فِي سَبِيلِهِ بَيْنَ كُلِّ دَرَجَتَيْنِ كَمَا بَيْنَ السَّمَاءِ وَالْأَرْضِ فَإِذَا سَأَلْتُمْ اللَّهَ عَزَّ وَجَلَّ فَسَلُوهُ الْفِرْدَوْسَ فَإِنَّهُ وَسَطُ الْجَنَّةِ وَأَعْلَى الْجَنَّةِ وَفَوْقَ عَرْشِ الرَّحْمَنِ عَزَّ وَجَلَّ وَمِنْهُ تَفَجَّرُ ‏ ‏أَوْ تَنْفَجِرُ أَنْهَارُ الْجَنَّةِ شَكَّ ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏أَوْ ‏ ‏ابْنِ أَبِي عَمْرَةَ ‏ ‏قَالَ ‏ ‏فُلَيْحٌ ‏ ‏وَلَا أَعْلَمُهُ إِلَّا عَنْ ‏ ‏ابْنِ أَبِي عَمْرَةَ ‏ ‏فَذَكَرَ الْحَدِيثَ إِلَّا أَنَّهُ قَالَ تَفَجَّرُ أَنْهَارُ الْجَنَّةِ وَقَالَ أَفَلَا نُنَبِّئُ النَّاسَ بِذَلِكَ ‏ ‏قَالَ ‏ ‏وَحْدَهُ ‏ ‏ثُمَّ حَدَّثَنَا بِهِ فَلَمْ يَشُكَّ ‏ ‏يَعْنِي ‏ ‏فُلَيْحًا ‏ ‏قَالَ ‏ ‏عَطَاءُ بْنُ يَسَارٍ ‏ ‏فَحَدَّثَنَاهُ ‏ ‏سُرَيْجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَهُ وَقَالَ وَفَوْقَهُ عَرْشُ الرَّحْمَنِ وَمِنْهُ تَنْفَجِرُ أَنْهَارُ الْجَنَّةِ ‏","","",""],[8068,8068,"","আমার ভাইকে মুক্ত হওয়ার ব্যাপারে কথা বলার জন্য বলা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الشَّيْخُ يَكْبَرُ وَيَضْعُفُ جِسْمُهُ وَقَلْبُهُ شَابٌّ عَلَى حُبِّ اثْنَيْنِ طُولِ الْعُمُرِ وَالْمَالِ ‏","","",""],[8069,8069,"","আমরা বলেছিলাম যে, তিনি আমাকে একটা হাত দিয়েছিলেন । ভাববাদীরা আমাকে বলেছিল যে, আমরা তাঁর হাতে দ্বারা নির্ধারিত হয়েছি, তারা তাঁর ইচ্ছা রক্ষা করেছে এবং তাঁর আজ্ঞা পালন করে আসছে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏وَسُرَيْجٌ ‏ ‏قَالَا ثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ أَهْلَ الْجَنَّةِ لَيَتَزَاوَرُونَ فِيهَا ‏ ‏قَالَ ‏ ‏سُرَيْجٌ ‏ ‏لَيَتَرَاءَوْنَ ‏ ‏فِيهَا ‏ ‏كَمَا ‏ ‏تَرَاءَوْنَ الْكَوْكَبَ الشَّرْقِيَّ وَالْكَوْكَبَ الْغَرْبِيَّ الْغَارِبَ فِي ‏ ‏الْأُفُقِ ‏ ‏الطَّالِعَ فِي تَفَاضُلِ الدَّرَجَاتِ قَالُوا يَا رَسُولَ اللَّهِ أُولَئِكَ النَّبِيُّونَ قَالَ بَلَى وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ أَقْوَامٌ آمَنُوا بِاللَّهِ وَرَسُولِهِ وَصَدَّقُوا الْمُرْسَلِينَ ‏ ‏وَقَالَ ‏ ‏سُرَيْجٌ ‏ ‏أَقْوَامٌ آمَنُوا بِاللَّهِ ‏","","",""],[8070,8070,"","আমরা এক দীর্ঘ সময় ধরে এক স্বপ্ন সম্বন্ধে কথা বলেছিলাম, যাতে সতর্ক থাকার জন্য ভাববাদী তার জন্য প্রার্থনা করেছিলেন এবং তাকে একটা স্বপ্ন জিজ্ঞেস করেছিলেন । আমার নিজের পরিকল্পনা থেকে তাকে ঈশ্বর থেকে দূরে সরিয়ে নেননি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ حَلْحَلَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا يُصِيبُ الْمَرْءَ الْمُسْلِمَ مِنْ ‏ ‏نَصَبٍ ‏ ‏وَلَا ‏ ‏وَصَبٍ ‏ ‏وَلَا هَمٍّ وَلَا حُزْنٍ وَلَا غَمٍّ وَلَا أَذًى حَتَّى الشَّوْكَةَ يُشَاكُهَا إِلَّا كَفَّرَ اللَّهُ عَنْهُ بِهَا مِنْ خَطَايَاهُ ‏","","",""],[8071,8071,"","আমরা একটি সুখী পুত্র কথা বলেছি যে আমার শ্বশুর আব্বার কথা বলেছে। লর্ড তার কাছে প্রার্থনা করল এবং তার কাছে প্রার্থনা করল, যে তিনজন কন্যার কন্যার সাথে প্রার্থনা করল এবং তাদের প্রাণ হারিয়েছে। তার দয়া, তারা বলে মানুষ বা দুই ঈশ্বর বলে, \"আমি একজন মানুষ\"","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ مَسْعَدَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَ لَهُ ثَلَاثُ بَنَاتٍ فَصَبَرَ عَلَى ‏ ‏لَأْوَائِهِنَّ ‏ ‏وَضَرَّائِهِنَّ وَسَرَّائِهِنَّ أَدْخَلَهُ اللَّهُ الْجَنَّةَ بِفَضْلِ رَحْمَتِهِ إِيَّاهُنَّ فَقَالَ رَجُلٌ أَوْ ثِنْتَانِ يَا رَسُولَ اللَّهِ قَالَ أَوْ ثِنْتَانِ فَقَالَ رَجُلٌ أَوْ وَاحِدَةٌ يَا رَسُولَ اللَّهِ قَالَ أَوْ وَاحِدَةٌ ‏","","",""],[8072,8072,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন আর আমি আমার বাবাকে এই বিষয়টা জেনে আনন্দ দেব যে, তুমি যে - আনন্দ পেয়েছ, তা আমি তোমাকে দিতে পারব । আমার বাবা-মা বলেছে, ওমরকে আমি বলছি ওনা... \"বাবা\" বললো, \"বাবা\", সে গুহার বিছানায় আছে আর যদি তুমি তোমার সেক্সকে কিছু বলতে দাও আমি ঈশ্বরের কাছে যেতে দিতে পারব না।","‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بَلْجٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ لِي نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏هَلْ أَدُلُّكَ عَلَى كَلِمَةٍ كَنْزٍ مِنْ كَنْزِ الْجَنَّةِ تَحْتَ الْعَرْشِ قَالَ قُلْتُ نَعَمْ فِدَاكَ أَبِي وَأُمِّي قَالَ أَنْ تَقُولَ لَا قُوَّةَ إِلَّا بِاللَّهِ ‏ ‏قَالَ ‏ ‏أَبُو بَلْجٍ ‏ ‏وَأَحْسَبُ أَنَّهُ قَالَ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ أَسْلَمَ عَبْدِي وَاسْتَسْلَمَ ‏ ‏قَالَ ‏ ‏فَقُلْتُ ‏ ‏لِعَمْرٍو ‏ ‏قَالَ ‏ ‏أَبُو بَلْجٍ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏قُلْتُ ‏ ‏لِأَبِي هُرَيْرَةَ ‏ ‏لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ فَقَالَ ‏ ‏لَا إِنَّهَا فِي سُورَةِ ‏ ‏الْكَهْفِ ‏ { ‏وَلَوْلَا إِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَاءَ اللَّهُ لَا قُوَّةَ إِلَّا بِاللَّهِ ‏}","","",""],[8073,8073,"","আমরা দুজন সালামকে যুদ্ধের সাথে নিয়ে তৈরি করেছি, যে কিনা এক ছেলে হবার স্বপ্ন নিয়ে আমরা যা করেছি, তা হচ্ছে আমার বাবা তার কাছে একটা ভবিষ্যদ্বাণীর উপহার, যে তাকে আদেশ দিয়েছিল এবং সে একজন পুরুষ ছিল জাহাজের মধ্যে যে - দুর্বলগুলো ছিল সেগুলো বিক্রি করে তিনি একটা সর্পের মধ্যে ছিলেন । ডরোনার, জাহাজ কিছুই রেখে যায়নি।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَجُلًا كَانَ يَبِيعُ الْخَمْرَ فِي سَفِينَةٍ وَكَانَ يَشُوبُهُ بِالْمَاءِ وَكَانَ مَعَهُ فِي السَّفِينَةِ قِرْدٌ قَالَ فَأَخَذَ الْكِيسَ وَفِيهِ الدَّنَانِيرُ قَالَ فَصَعِدَ ‏ ‏الذَّرْوَ ‏ ‏يَعْنِي ‏ ‏الدَّقَلَ ‏ ‏فَفَتَحَ الْكِيسَ فَجَعَلَ يُلْقِي فِي الْبَحْرِ ‏ ‏دِينَارًا وَفِي السَّفِينَةِ دِينَارًا حَتَّى لَمْ يَبْقَ فِيهِ شَيْءٌ ‏","","",""],[8074,8074,"","আমার বাবা এমন একটা উপহার, যা ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তিনি তা দিয়েছেন । পরম করুণাময়ের মহিমা, বৃদ্ধ মহিলা আর বাকি সবাই শেষ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ مُسْلِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ صُفُوفِ الرِّجَالِ الْمُقَدَّمُ وَشَرُّهَا الْمُؤَخَّرُ وَشَرُّ صُفُوفِ النِّسَاءِ الْمُقَدَّمُ وَخَيْرُهَا الْمُؤَخَّرُ ‏","","",""],[8075,8075,"","আমরা যেবুটি নিয়ে কথা বলেছি, আমি আমার বাবার সাথে কথা বলেছি, আমি শপথ নিয়ে বলছি আমি ঈশ্বরের কাছে যাচ্ছি আমি তাকে ফোন করব এবং বলে দেব সে মারা গেছে। তুমি যা বলেছ, আমরা ঘুমিয়েছি বা ঘুমিয়েছি, তার সম্পর্কে। বিবরণ বলে যে, তার জীবন হয়তো প্রপৌত্র থেকে বাদ দেওয়া হবে না ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ قُلْتُ ‏ ‏لِأَبِي هُرَيْرَةَ ‏ ‏أَهَكَذَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِكُمْ قَالَ وَمَا أَنْكَرْتَ مِنْ صَلَاتِي قَالَ قُلْتُ أَرَدْتُ أَنْ أَسْأَلَكَ عَنْ ذَلِكَ قَالَ نَعَمْ ‏ ‏وَأَوْجَزُ قَالَ ‏ ‏وَكَانَ قِيَامُهُ قَدْرَ مَا يَنْزِلُ الْمُؤَذِّنُ مِنْ الْمَنَارَةِ وَيَصِلُ إِلَى الصَّفِّ ‏","","",""],[8076,8076,"","আমার ভাই যখন জন্মগ্রহন করল, তখন আমি যে বধিরদের কথা বলেছিলাম, সে বিষয়ে কথা বলেছি। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তাকে তার আত্মার ধার্মিকতার কথা থেকে বের করে দেবেন। বলতে গেলে আমি তার প্রত্যেক ঘোড়া আর তার সব দাবিরই খেয়ে ফেলেছি.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْرُجُ عُنُقٌ مِنْ النَّارِ يَوْمَ الْقِيَامَةِ لَهُ عَيْنَانِ يُبْصِرُ بِهِمَا ‏ ‏وَأُذُنَانِ ‏ ‏يَسْمَعُ بِهِمَا وَلِسَانٌ يَنْطِقُ بِهِ فَيَقُولُ إِنِّي وُكِّلْتُ بِثَلَاثَةٍ بِكُلِّ جَبَّارٍ عَنِيدٍ وَبِكُلِّ مَنْ ادَّعَى مَعَ اللَّهِ إِلَهًا آخَرَ وَالْمُصَوِّرِينَ ‏","","",""],[8077,8077,"","আমরা দুই বছর আগে আমার বাবার ছেলে বিয়ের জন্য যাচ্ছে কথা বলেছিলাম। আমি তার জন্য প্রার্থনা করি এবং তাকে বলতে চাই, তোমার মতো সে কতগুলো লোক পড়ে গেছে। আর তোমার মা ছিল.","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏مَوْلَى ‏ ‏أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَيْفَ بِكُمْ إِذَا نَزَلَ فِيكُمْ ‏ ‏عِيسَى ابْنُ مَرْيَمَ ‏ ‏وَإِمَامُكُمْ مِنْكُمْ ‏","","",""],[8078,8078,"","আমি আমার বাবার ছেলেকে বলেছিলাম আমার ভাইকে সাহায্য করার জন্য যেতে। সে শান্তি পাবে না। তার প্রতিবেশী বলেছেন, তার কার্ড এবং কার্ড ও চিঠি রক্ষা পাবে না। তার পরিচয় পত্রে তার আলো লেখা ছিল।","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا وَاللَّهِ لَا يُؤْمِنُ لَا وَاللَّهِ لَا يُؤْمِنُ لَا وَاللَّهِ لَا يُؤْمِنُ قَالُوا وَمَنْ ذَاكَ يَا رَسُولَ اللَّهِ قَالَ جَارٌ لَا يَأْمَنُ جَارُهُ بَوَائِقَهُ قِيلَ وَمَا بَوَائِقُهُ قَالَ شَرُّهُ ‏","","",""],[8079,8079,"","আমরা কথা বলেছিলাম আমার বাবা আমার কাছে যাওয়ার চেষ্টা করছেন। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমি আত্মসমর্পণ করব যে, এমনকি আপনি তার গ্রহণ আগে আমার মায়ের জীবনও কেড়ে নেবেন না। জীবন, ঈশ্বরের দোহাই, সে কিভাবে রাম করলো আর মদটা বললো যখন মানুষ তোমাকে ভরে নি।","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ أَبُو مُحَمَّدٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى تَأْخُذَ أُمَّتِي أَخْذَ الْأُمَمِ قَبْلَهَا شِبْرًا بِشِبْرٍ وَذِرَاعًا بِذِرَاعٍ قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ كَمَا فَعَلَتْ ‏ ‏فَارِسُ ‏ ‏وَالرُّومُ ‏ ‏قَالَ وَمَا النَّاسُ إِلَّا أُولَئِكَ ‏","","",""],[8080,8080,"","আমরা তোমার বাবার কথা বলেছিলাম একজন মরণশীল বাধ্যতা নিয়ে জন্ম নেয়া সম্পর্কে। তিনি আমাকে শিখিয়েছিলেন তিনি শপথ নিতে পারেন আর একজন যাজকের দ্বারা তিনি আশীর্বাদ প্রাপ্ত হয়েছেন যে তার বাবার নামে শপথ নিতে পারে। আমি করব. ঈশ্বরের কাছে প্রার্থনা করো আর সে এটা ভুলে যাবে, ঈশ্বর তোমাকে যা খেতে বলেছেন তা দিতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ بْنُ عُمَرَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَتَى أَعْرَابِيٌّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأَرْنَبٍ قَدْ شَوَاهَا وَمَعَهَا ‏ ‏صِنَابُهَا ‏ ‏وَأَدَمُهَا فَوَضَعَهَا بَيْنَ يَدَيْهِ فَأَمْسَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يَأْكُلْ وَأَمَرَ أَصْحَابَهُ أَنْ يَأْكُلُوا فَأَمْسَكَ الْأَعْرَابِيُّ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يَمْنَعُكَ أَنْ تَأْكُلَ قَالَ إِنِّي أَصُومُ ثَلَاثَةَ أَيَّامٍ مِنْ الشَّهْرِ قَالَ إِنْ كُنْتَ صَائِمًا فَصُمْ الْأَيَّامَ ‏ ‏الْغُرَّ ‏","","",""],[8081,8081,"","আমি আমার বাবাকে মুক্ত করার চেষ্টা করার বিষয়ে আমার বাবার সঙ্গে কথা বলার চেষ্টা করেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَعْتَكِفُ الْعَشْرَ الْأَوَاخِرَ مِنْ شَهْرِ رَمَضَانَ فَلَمَّا كَانَ الْعَامُ الَّذِي قُبِضَ فِيهِ اعْتَكَفَ عِشْرِينَ ‏","","",""],[8082,8082,"","আমরা ফিরে যাওয়ার কথা বলছিলাম আর আমার বাবার দু'জন ছেলেকে আমরা বলেছিলাম কিভাবে অনুভব করতে হয়। আমার বাবার স্বপ্ন ছিল তার শান্তির জন্য। দিনের দৃষ্টি সরিয়ে রেখে, এডনো এর বয়স বলে আমরা সবাই শিকারীরা তোমার শেষ পথে চলে যাচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ سَعْدٍ وَهُوَ أَبُو دَاوُدَ الْحَفَرِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِطَعَامٍ ‏ ‏بِمَرِّ الظَّهْرَانِ ‏ ‏فَقَالَ ‏ ‏لِأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏ادْنُوَا ‏ ‏فَكُلَا قَالَا إِنَّا صَائِمَانِ قَالَ ارْحَلُوا لِصَاحِبَيْكُمْ اعْمَلُوا لِصَاحِبَيْكُمْ ‏","","",""],[8083,8083,"","আমরা অনেক খুশি হয়েছি, কিন্তু আমার বাবার কথা চিন্তা করে একটা ছেলে, যে কেকের কেক নিয়ে বের হবে, লর্ড বলেছেন, ঈশ্বর প্রার্থনা করেছেন। তাকে আর ঈশ্বরের বজ্র দিয়ে উদ্ধার করা হবে, তুমি বলতে চাচ্ছ আমরা হাঙ্গরই করি।","‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ طَارِقٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْرَعُ قَبَائِلِ ‏ ‏الْعَرَبِ ‏ ‏فَنَاءً ‏ ‏قُرَيْشٌ ‏ ‏وَيُوشِكُ أَنْ تَمُرَّ الْمَرْأَةُ بِالنَّعْلِ فَتَقُولَ إِنَّ هَذَا نَعْلُ قُرَشِيٍّ ‏","","",""],[8084,8084,"","আমরা বাবার সাথে তার বাবার কথা বলেছিলাম তার বাবার সাথে কুঁড়েঘ্যানের কথা। ঈশ্বর দাবি করেছেন, আমরা সেই লোকদের খুঁজে বের করবো যাদের ঈশ্বরের ইচ্ছা আছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏قُطْبَةُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَجِدُ مِنْ شَرِّ النَّاسِ عِنْدَ اللَّهِ ذَا الْوَجْهَيْنِ ‏","","",""],[8085,8085,"","আমরা বাবার স্বপ্নের কথা বলেছিলাম... ...একজন জিনিয়াসের প্রতি বাবার ভালোবাসা নিয়ে... ...আর ঈশ্বরের কাছে প্রার্থনা করবে... ...যদি আমি তাকে বিক্রি করে দেই...","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَرَقَ عَبْدُ أَحَدِكُمْ فَلْيَبِعْهُ وَلَوْ ‏ ‏بِنَشٍّ ‏","","",""],[8086,8086,"","আমরা প্রেম নিয়ে কথা বলেছি, এক বছর সুভা হারিয়ে গেছে, ঈশ্বর হয়ত বলতে পারেন ঈশ্বর তাঁর ইচ্ছার জন্য প্রার্থনা করেছেন। তিনি একটি টোপ কিনেছেন, এমনকি তিনি এটা বিক্রি করতে পারেন না।","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنِي ‏ ‏الضَّحَّاكُ بْنُ عُثْمَانَ ‏ ‏فِي سَنَةِ إِحْدَى وَخَمْسِينَ خَرَجْتُ مَعَ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بُكَيْرُ بْنُ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اشْتَرَى طَعَامًا فَلَا يَبِعْهُ حَتَّى ‏ ‏يَسْتَوْفِيَهُ ‏","","",""],[8087,8087,"","আমরা ঐ বধিরদের কথা বলেছিলাম যে আমার বাবা কিভাবে ঈশ্বরের পথে যাচ্ছে, সে বলবে যদি সে তোমাকে হত্যা করে, তার ভাই তার চেহারার সম্মুখীন হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَاتَلَ أَحَدُكُمْ أَخَاهُ فَلْيَجْتَنِبْ الْوَجْهَ ‏","","",""],[8088,8088,"","ঈশ্বর যদি কেবল একবারই তাঁর কাছে আসবেন, তা হলে তিনি তার কাছে আত্মসমর্পণ করবেন । তারা যেভাবে বলেছে সেভাবেই বেঁচে থাকতে... ...আমি একটা ছেলে হতে যাচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا ثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَافَرْتُمْ فِي ‏ ‏الْخِصْبِ ‏ ‏فَأَعْطُوا الْإِبِلَ حَقَّهَا وَإِذَا سَافَرْتُمْ فِي ‏ ‏الْجَدْبِ ‏ ‏فَأَسْرِعُوا السَّيْرَ وَإِذَا أَرَدْتُمْ ‏ ‏التَّعْرِيسَ ‏ ‏فَتَنَكَّبُوا ‏ ‏عَنْ الطَّرِيقِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَنَا ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏","","",""],[8089,8089,"","আমরা সেই বধিরদের কথা বলেছিলাম যে আমার বাবা কিভাবে ঈশ্বরের পথে যাচ্ছে সে ব্যাপারে কথা বলেছি। সে বলবে যে তুমি মৃত্যুর যোগ্য নও...","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَجْعَلُوا بُيُوتَكُمْ مَقَابِرَ فَإِنَّ الشَّيْطَانَ يَفِرُّ مِنْ الْبَيْتِ إِنْ يَسْمَعْ سُورَةَ ‏ ‏الْبَقَرَةِ ‏ ‏تُقْرَأُ فِيهِ ‏","","",""],[8090,8090,"","আমরা সেই বধিরদের কথা বলেছি, যাদের আমরা পিতা-মাতা-এর পৃথিবীতে ঘটেছে এবং আমরা যা করেছি তা হচ্ছে আমাদের দুই গোপন বিষয়, আমার বাবা আছে, ঈশ্বর, যদি আমার কলার একটা মুক্ত জিনিস কাজ করে, যদি আমি তা করি। আমরা এটা কিনে নিতাম, তারপর আমরা ভালো থাকবো। যখন librks পরত না, যাদের সাথে কোন সম্পর্ক নেই","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏سَالِمٌ أَبُو جُمَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سِيرِينَ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏حَدَّثَ أَنَّ ‏ ‏عُمَرَ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏عُطَارِدًا التَّمِيمِيَّ ‏ ‏كَانَ يُقِيمُ ‏ ‏حُلَّةَ ‏ ‏حَرِيرٍ فَلَوْ اشْتَرَيْتَهَا فَلَبِسْتَهَا إِذَا جَاءَكَ وُفُودُ النَّاسِ قَالَ فَقَالَ ‏ ‏إِنَّمَا يَلْبَسُ الْحَرِيرَ مَنْ لَا ‏ ‏خَلَاقَ ‏ ‏لَهُ ‏","","",""],[8091,8091,"","আমার বাবা একজন দেবতা হওয়ার স্বপ্ন নিয়ে কথা বলেছিলাম, ঈশ্বরের দয়া ছিল আমার বাবা ছিলেন একজন জিনিয়াস, যিনি সূর্যের শেষ প্রান্তে বিশ্বাস করতেন না। তীব্রতা:% 1","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏وَاللَّهِ إِنِّي لَأَقْرَبُكُمْ صَلَاةً بِرَسُولِ اللَّهِ وَكَانَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يَقْنُتُ فِي الرَّكْعَةِ الْآخِرَةِ مِنْ صَلَاةِ الْعِشَاءِ الْآخِرَةِ وَصَلَاةِ الصُّبْحِ بَعْدَمَا يَقُولُ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَيَدْعُو لِلْمُؤْمِنِينَ وَيَلْعَنُ الْكُفَّارَ ‏","","",""],[8092,8092,"","আমরা একটা ছেলের কথা বলেছি যে আমার বাবাকে কিভাবে উপাসনা করতে হয়, ঈশ্বর বললেন যে তারা ছয় বছর কাজ করেছে তার বস্তা আর অদ্ভুত জিনিস থেকে. আমি প্রতিজ্ঞা করছি আমি তোমার. সাধারণ দিয়ে যায়","‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ يَعْنِي ابْنَ بِلَالٍ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَادِرُوا بِالْأَعْمَالِ سِتًّا طُلُوعَ الشَّمْسِ مِنْ مَغْرِبِهَا ‏ ‏وَالدَّجَّالَ ‏ ‏وَالدُّخَانَ وَالدَّابَّةَ وَخَاصَّةَ أَحَدِكُمْ وَأَمْرَ الْعَامَّةِ ‏","","",""],[8093,8093,"","আমরা তার ছেলেকে বললাম যে আমার ছেলে নির্দোষ, আল্লাহ আছে আর সে বলবে যে সে বিশ্বাস করতে পারবে না যে সে অভিশপ্ত হবে।","‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ يَعْنِي ابْنَ بِلَالٍ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَنْبَغِي لِلصَّدِيقِ أَنْ يَكُونَ ‏ ‏لَعَّانًا ‏","","",""],[8094,8094,"","ঈশ্বর তাকে আত্মসমর্পণ করতে বলেছেন আর তাই তিনি এটা করতে পারবেন যে ঈশ্বর আমার জয় করেছেন আর ভয় পাবে আমার কোন বক্তৃতা নেই।","‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا جَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏سَعِّرْ ‏ ‏فَقَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يَرْفَعُ وَيَخْفِضُ وَلَكِنِّي لَأَرْجُو أَنْ أَلْقَى اللَّهَ عَزَّ وَجَلَّ وَلَيْسَ لِأَحَدٍ عِنْدِي مَظْلِمَةٌ ‏","","",""],[8095,8095,"","আমরা বাবার ভালবাসার কথা মুছে ফেলার চেষ্টা করেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং ককেশাসের অতিথিদের অভিশাপ প্রদান করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ زَوَّارَاتِ الْقُبُورِ ‏","","",""],[8096,8096,"","আমরা এই খবর মুছে ফেলার চেষ্টা করেছি যে বাবা আমাদের চেয়ে ভালো বলেছেন। আমার বাবার জন্য, যে ঈশ্বরকে জিজ্ঞেস করতে বলেছে, আল্লাহ যেন তার ইচ্ছা পূরণ করেন এবং তাকে জিজ্ঞেস করেন। আমাদের মধ্যে একজন মুক্তির জন্য.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏وَحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏أُحُدًا ‏ ‏هَذَا يُحِبُّنَا وَنُحِبُّهُ ‏","","",""],[8097,8097,"","আমরা সবাই বলেছিলাম যে আমার বাবা ঈশ্বরের পুত্রের স্বপ্নের কথা বলতে পারে, সে যদি গেম চুরি করে তাহলে তাকে উদ্ধার করতে হবে, আর সে একটা বাচ্চা পেয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَرَقَ الْعَبْدُ فَبِعْهُ وَلَوْ ‏ ‏بِنَشٍّ ‏ ‏يَعْنِي بِنِصْفِ ‏ ‏أُوقِيَّةٍ ‏","","",""],[8098,8098,"","আমরা বাবার ভালবাসার কথা মুছে ফেলার চেষ্টা করেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং ককেশাসের অতিথিদের অভিশাপ প্রদান করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ زَوَّارَاتِ الْقُبُورِ ‏","","",""],[8099,8099,"","আমরা দুজন ভালো ছেলের কথা বলেছি যারা আমার সাথে এক জবানবন্দী ছেলে হিসেবে কথা বলেছে। আমার বাবা তাকে একটি আশীর্বাদ করেছেন। দুই সপ্তাহের মধ্যে হারিয়ে যায় এবং বার বার আমি তাদের সাথে পরিচিত হই, কারণ বৃষ্টি হচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ يَعْنِي ابْنَ حَازِمٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيَنْزِلَنَّ ‏ ‏الدَّجَّالُ ‏ ‏خُوزَ ‏ ‏وَكَرْمَانَ ‏ ‏فِي سَبْعِينَ أَلْفًا وُجُوهُهُمْ ‏ ‏كَالْمَجَانِّ ‏ ‏الْمُطْرَقَةِ ‏","","",""],[8100,8100,"","আমরা আমার ভাই হার্লেকে সাহায্য করার কথা বলেছিলাম, তাকে হারলির কাছে আত্মসমর্পণ করতে হবে যদি সে সাধারণের মত সহজ পথে ফিরে যায়। পৃথিবী.","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَرَجَ إِلَى الْعِيدَيْنِ رَجَعَ فِي غَيْرِ الطَّرِيقِ الَّذِي خَرَجَ فِيهِ ‏","","",""],[8101,8101,"","আমরা ঈশ্বরের আশীর্বাদ নিয়ে একটা জিনিয়াসকে সাহায্য করার পর তার জন্য প্রার্থনা করেছি। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং আশ্বস্ত করেছেন যে ঈশ্বর আমার প্রতি ভালবাসা প্রকাশ করবেন না।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ ‏ ‏أَيْنَ الْمُتَحَابُّونَ بِجَلَالِي ‏ ‏الْيَوْمَ أُظِلُّهُمْ فِي ظِلِّي يَوْمَ لَا ظِلَّ إِلَّا ظِلِّي ‏","","",""],[8102,8102,"","বেনকে তার কাছে গোপন রাখার কথা বলেছিলাম, সে বলে যে প্রাচীনরা বলবে সে তার শরীর ভেঙ্গে ফেলবে আর বলবে সে পঙ্গু হয়ে যাবে. আর টাকার জন্য তাকে টাকা দিবে.","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏ثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الشَّيْخَ ‏ ‏قَالَ ‏ ‏يُونُسُ ‏ ‏أَظُنُّهُ قَالَ ‏ ‏يَهْرَمُ ‏ ‏وَيَضْعُفُ جِسْمُهُ وَقَلْبُهُ شَابٌّ عَلَى حُبِّ اثْنَيْنِ طُولِ الْحَيَاةِ وَحُبِّ الْمَالِ ‏","","",""],[8103,8103,"","আমরা ঈশ্বরের ছেলের সাথে ঘুমাতাম, আমরা ঈশ্বরের সাহায্য করার চেষ্টা করতাম। আমার বাবা তার প্রভুর কাছে বলেছে, সে এটা করতে জানে না। সে যে অপরাধ সম্পর্কে জানতে পারে নি, সে অন্ধ হয়ে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَسُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏قَالَا ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ أَبِي طُوَالَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَعَلَّمَ عِلْمًا مِمَّا ‏ ‏يُبْتَغَى ‏ ‏بِهِ وَجْهُ اللَّهِ لَا يَتَعَلَّمُهُ إِلَّا لِيُصِيبَ بِهِ ‏ ‏عَرَضًا ‏ ‏مِنْ الدُّنْيَا لَمْ يَجِدْ ‏ ‏عَرْفَ ‏ ‏الْجَنَّةِ يَوْمَ الْقِيَامَةِ ‏ ‏قَالَ ‏ ‏سُرَيْجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏يَعْنِي رِيحَهَا ‏","","",""],[8104,8104,"","আমি বাবার শেষ বাবার সঙ্গে তাকে সাহায্য করার বিষয়ে কথা বলেছিলাম । যদি তারা জানত যে এটার কোন মূল্য নেই।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَسُرَيْجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عُبَيْدِ بْنِ السَّبَّاقِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏تُفْتَحُ الْبِلَادُ ‏ ‏وَالْأَمْصَارُ ‏ ‏فَيَقُولُ الرِّجَالُ لِإِخْوَانِهِمْ ‏ ‏هَلُمُّوا ‏ ‏إِلَى الرِّيفِ ‏ ‏وَالْمَدِينَةُ ‏ ‏خَيْرٌ لَهُمْ لَوْ كَانُوا يَعْلَمُونَ لَا يَصْبِرُ عَلَى ‏ ‏لَأْوَائِهَا ‏ ‏وَشِدَّتِهَا أَحَدٌ إِلَّا كُنْتُ لَهُ يَوْمَ الْقِيَامَةِ شَهِيدًا ‏ ‏أَوْ شَفِيعًا ‏","","",""],[8105,8105,"","আমি আমার বাবার চেয়ে আগে বেনকে সাহায্য করার কথা বলেছিলাম । যে বিশ্বাসঘাতকরা দেখতে পায়... ...যে বলছে, গোপন আর প্রভুর চোখে দেখে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَسُرَيْجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عُبَيْدِ بْنِ السَّبَّاقِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبْلَ السَّاعَةِ ‏ ‏سِنُونَ خَدَّاعَةٌ يُكَذَّبُ فِيهَا الصَّادِقُ وَيُصَدَّقُ فِيهَا الْكَاذِبُ وَيُخَوَّنُ فِيهَا الْأَمِينُ وَيُؤْتَمَنُ فِيهَا الْخَائِنُ وَيَنْطِقُ فِيهَا ‏ ‏الرُّوَيْبِضَةُ ‏ ‏قَالَ ‏ ‏سُرَيْجٌ ‏ ‏وَيَنْظُرُ فِيهَا ‏ ‏الرُّوَيْبِضَةُ ‏","","",""],[8106,8106,"","আমরা আমার বাবার সাথে দেবী হওয়ার কথা বলেছিলাম. ঈশ্বরের বলতে হবে আমি যে সাধারণ মানুষ আমি আমার হাতে দুই গুজবের মধ্যে ছিলাম.","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ فِيمَا يَرَى النَّائِمُ كَأَنَّ فِي يَدَيَّ سِوَارَيْنِ مِنْ ذَهَبٍ فَنَفَخْتُهُمَا فَرُفِعَا ‏ ‏فَأَوَّلْتُ ‏ ‏أَنَّ أَحَدَهُمَا ‏ ‏مُسَيْلِمَةُ ‏ ‏وَالْآخَرَ ‏ ‏الْعَنْسِيُّ ‏","","",""],[8107,8107,"","ঈশ্বর তাকে আদেশ দিয়েছেন এবং তার সঙ্গে দুটো শব্দ পাওয়া যায় আর তারপর কেটে ফেলতে হয় ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং আমি যখন তোমাকে রক্ষা করার আদেশ দিয়েছিলাম, তখন আত্মসমর্পণ করব । ওদের খুঁজে বের করতে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏بُكَيْرٌ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏بَعَثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْثٍ فَقَالَ ‏ ‏إِنْ وَجَدْتُمْ ‏ ‏فُلَانًا ‏ ‏وَفُلَانًا ‏ ‏لِرَجُلَيْنِ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏فَأَحْرِقُوهُمَا بِالنَّارِ ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أَرَدْنَا الْخُرُوجَ إِنِّي كُنْتُ أَمَرْتُكُمْ أَنْ تُحْرِقُوا ‏ ‏فُلَانًا ‏ ‏وَفُلَانًا ‏ ‏بِالنَّارِ وَإِنَّ النَّارَ لَا يُعَذِّبُ بِهَا إِلَّا اللَّهُ تَعَالَى فَإِنْ وَجَدْتُمُوهُمَا فَاقْتُلُوهُمَا ‏","","",""],[8108,8108,"","আমি বাবার জন্য যা চিন্তা করি তা আমার বাবার জন্য সবচেয়ে ভালো। সে ঈশ্বরের কাছে প্রার্থনা করল, সে তার বসত না কিন্তু সে তোমাকে ক্ষমা করে দিত।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ أَبِي يَعْقُوبَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُقِيمُ الرَّجُلُ الرَّجُلَ مِنْ مَجْلِسِهِ وَلَكِنْ افْسَحُوا يَفْسَحْ اللَّهُ لَكُمْ ‏","","",""],[8109,8109,"","আমি বাবার স্বপ্নের মাধ্যমে আমার বাবাকে পরাজিত করার বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمُهَزِّمِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسَبْعَةِ أَضُبٍّ عَلَيْهَا تَمْرٌ وَسَمْنٌ فَقَالَ ‏ ‏كُلُوا فَإِنِّي أَعَافُهَا ‏","","",""],[8110,8110,"","বাবার সাথে কথা বলেছি, আমি গাছের ভিতর দিয়ে যাচ্ছিলাম, যদি আমি কিছু করি, সে পেয়ে গেছে!","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُهَزِّمِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ ‏ ‏بِسَخْلَةٍ ‏ ‏جَرْبَاءَ قَدْ أَخْرَجَهَا أَهْلُهَا فَقَالَ ‏ ‏أَتَرَوْنَ هَذِهِ هَيِّنَةً عَلَى أَهْلِهَا قَالُوا نَعَمْ قَالَ لَلدُّنْيَا أَهْوَنُ عَلَى اللَّهِ عَزَّ وَجَلَّ مِنْ هَذِهِ عَلَى أَهْلِهَا ‏","","",""],[8111,8111,"","আমরা এমন এক শিকারীর কথা বলেছি, যিনি বাবাকে হারাহরা বলে যে সে শিকারী, ঈশ্বর তাকে আদেশ দিয়েছেন আর তাকে আত্মসমর্পণ করতে হবে যদি তার উপহার থাকে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُتِيَ بِطَعَامٍ مِنْ غَيْرِ أَهْلِهِ سَأَلَ عَنْهُ فَإِنْ قِيلَ لَهُ هَدِيَّةٌ أَكَلَ وَإِنْ قِيلَ ‏ ‏صَدَقَةٌ ‏ ‏قَالَ كُلُوا وَلَمْ يَأْكُلْ ‏","","",""],[8112,8112,"","আমি বাবার সাম্প্রতিক কিছু বিষয় নিয়ে কথা বলেছি, তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন যেন তিনি তার ইচ্ছা পূরণ করেন এবং তাকে উদ্ধার করা হয় এবং আমি যতদিন না ছিলাম ততক্ষণ পর্যন্ত সেবা করে যেতে পারে সে বলে যাবে তুমি তার বাড়িতে এসেছ আর আমরা ভুল করেছি.","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ أُقِيمَتْ ‏ ‏الصَّلَاةُ وَعُدِّلَتْ الصُّفُوفُ حَتَّى إِذَا قَامَ فِي مُصَلَّاهُ وَانْتَظَرْنَا أَنْ يُكَبِّرَ انْصَرَفَ فَقَالَ عَلَى مَكَانِكُمْ فَدَخَلَ بَيْتَهُ وَمَكَثْنَا عَلَى هَيْئَتِنَا حَتَّى خَرَجَ إِلَيْنَا وَرَأْسُهُ ‏ ‏يَنْطِفُ ‏ ‏وَقَدْ اغْتَسَلَ ‏","","",""],[8113,8113,"","আমরা ঈশ্বরের প্রেম নিয়ে কথা বলেছিলাম যখন আমার বাবা আমার গডফাদার কাছে এসেছিলেন, আর তিনি বললেন যে তিনি এমন একজন মানুষ যিনি আমাকে খেলা করতেন ঈশ্বর আমাদের জন্য দৌড়াচ্ছেন, ঈশ্বর তার উপর আছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَ رَجُلٌ يُدَايِنُ النَّاسَ فَكَانَ يَقُولُ لِفَتَاهُ إِذَا أَتَيْتَ مُعْسِرًا فَتَجَاوَزْ عَنْهُ لَعَلَّ اللَّهَ يَتَجَاوَزُ عَنَّا فَلَقِيَ اللَّهَ فَتَجَاوَزَ عَنْهُ ‏","","",""],[8114,8114,"","আমরা আমাদের সেরাটা করার চেষ্টা করেছি। আমার বাবা ঈশ্বরের কাছে প্রার্থনা করেছেন যেন তিনি আপনার আগের আগের সময়ে তার কাছে প্রার্থনা করেন। এবং এটা আমার মায়ের ছিল। এবং এটা ছিল আমার মায়ের কাছে অনেক কিছু। আমি আপনাদের কাছে একটি উপহার পেয়েছি। আমি আপনাদের জন্য একটি উপহার। আমি একটি উপহার পেয়েছি, আমি এটা নিয়ে এসেছি। আমি জানি, আমি এটা করতে পারি, আমি কি আপনার জন্য, আমি এটা করতে পারি? আমি জানি না? আমি এটা করতে পারি, আমি এটা আমার বাবা, আমি কি করতে পারি? আমি এটা করতে পারি? আমি যদি আমার বাবা, আমি এটা করতে চাই, আমি এটা করতে চাই। এবং আমি এটা করতে চাই। আমি এখন আমার বাবা, আমি কি করবো? আমি কি আপনার জন্য না যে, আমি কি করবো? আমি এটা আমার বাবা, আমি এটা করতে পারি? এবং আমি যখন আমার মা এটা করতে পারি, আমি এটা করতে পারি। এবং আমি যখন আমি যখন আমি এটা করতে পারি, তখন আমি যখন আমি যখন আমি এটা করতে পারি, তখন আমি এটা করতে পারি, তখন আমি যখন আমি এটা করতে পারি, তখন আমি যখন আমি তখন আমি এটা করতে পারি, তখন আমি যখন আমি তখন আমি এটা করতে পারি। এবং আমি যখন আমি যখন আমি যখন প্রথম বারের ছিলাম, তখন আমি এটা করি, তখন আমি যখন আমি এটা করি, তখন আমি এটা আমার মা নই। এবং আমি আমার বাবা এমন একজন ছেলের সঙ্গে কথা বলেছিলেন, যিনি হয়তো ঈশ্বরের কাছে তার প্রভুর কাছে পাঠিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏فَزَارَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ قَدْ ‏ ‏كَانَ فِيمَا مَضَى قَبْلَكُمْ مِنْ الْأُمَمِ نَاسٌ يُحَدَّثُونَ وَإِنَّهُ إِنْ كَانَ فِي أُمَّتِي هَذِهِ مِنْهُمْ أَحَدٌ فَإِنَّهُ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏و حَدَّثَنَاه ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَهُ مُرْسَلًا ‏","","",""],[8115,8115,"","আমরা আমার বাবার সঙ্গে কয়েক মাস আগে কথা বলেছিলাম । শহর, এই ছোট ছোটরা আমাকে বলেছে তোমার ঐ স্বৈরশাসকের দ্বারা যা বলেছে, তার জন্য, ঈশ্বর তার শান্তি নিয়ে আসবে তার কথা শোনার জন্য, বাবা, তুমি ঈর্ষান্বিত, ঈশ্বরের বার্তাবাহক।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا أَنَا نَائِمٌ رَأَيْتُنِي فِي الْجَنَّةِ فَإِذَا امْرَأَةٌ تَوَضَّأُ إِلَى جَنْبِ قَصْرٍ فَقُلْتُ لِمَنْ هَذَا الْقَصْرُ قَالُوا ‏ ‏لِعُمَرَ بْنِ الْخَطَّابِ ‏ ‏فَذَكَرْتُ غَيْرَتَكَ فَوَلَّيْتُ مُدْبِرًا ‏ ‏وَعُمَرُ ‏ ‏رَحِمَهُ اللَّهُ حِينَ يَقُولُ ذَلِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسٌ عِنْدَهُ مَعَ الْقَوْمِ فَبَكَى ‏ ‏عُمَرُ ‏ ‏حِينَ سَمِعَ ذَلِكَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَعَلَيْكَ بِأَبِي أَنْتَ أَغَارُ يَا رَسُولَ اللَّهِ ‏","","",""],[8116,8116,"","আমাদের বলা হয়েছে আমার বাবা একজন উৎপীড়ক ছিলেন আমাকে তিনি আদেশ করেছেন তিনি আত্মসমর্পণ করবেন তিনি বলেন তিনি পাগল হয়ে যাবেন অথবা মারা যাবেন. গৌল্ড এবং গৌল্ডের গর্ত এবং গর্ত ষাঁড়দের সঙ্গে যুদ্ধ করার পথে ঈশ্বর তাদের বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏فَزَارَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏هِلَالٍ يَعْنِي ابْنَ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَهْلَ الْجَنَّةِ لَيَتَرَاءَوْنَ فِي الْجَنَّةِ كَمَا ‏ ‏تَرَاءَوْنَ ‏ ‏أَوْ تَرَوْنَ ‏ ‏الْكَوْكَبَ ‏ ‏الدُّرِّيَّ ‏ ‏الْغَارِبَ فِي ‏ ‏الْأُفُقِ ‏ ‏وَالطَّالِعَ فِي تَفَاضُلِ الدَّرَجَاتِ قَالُوا يَا رَسُولَ اللَّهِ أُولَئِكَ النَّبِيُّونَ قَالَ بَلَى وَالَّذِي نَفْسِي بِيَدِهِ وَأَقْوَامٌ آمَنُوا بِاللَّهِ وَصَدَّقُوا الْمُرْسَلِينَ ‏","","",""],[8117,8117,"","আমরা আমাদের বলতে চেষ্টা করেছি যে কিভাবে আমার নিজের হাল ছেড়ে দিতে হয়।","‏ ‏حَدَّثَنَا ‏ ‏فَزَارَةُ ‏ ‏أَخْبَرَنَا ‏ ‏فُلَيْحٌ ‏ ‏وَسُرَيْجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الشَّيْخُ يَكْبَرُ وَيَضْعُفُ جِسْمُهُ وَقَلْبُهُ شَابٌّ عَلَى حُبِّ اثْنَتَيْنِ طُولِ الْحَيَاةِ وَحُبِّ الْمَالِ ‏ ‏وَقَالَ ‏ ‏سُرَيْجٌ ‏ ‏حُبِّ الْحَيَاةِ وَحُبِّ الْمَالِ ‏","","",""],[8118,8118,"","আমরা আমার ছেলেকে গোপন একটা রহস্য দেওয়ার কথা বলেছিলাম যেটা সে আমাকে একটা গোপন কথা বলবে। ঈশ্বর বলে দেবে, \"ঈশ্বরের কাছে তাঁর সংযোগ আছে এবং তার স্পর্শ উলকিতে পৌঁছাতে পারবে।\"","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْوَاصِلَةَ ‏ ‏وَالْمُسْتَوْصِلَةَ ‏ ‏وَالْوَاشِمَةَ ‏ ‏وَالْمُسْتَوْشِمَةَ ‏","","",""],[8119,8119,"","আমরা একটা সফর করেছি যখন আমি ঈশ্বরের ভালবাসার জন্য যুদ্ধ করতে বলেছিলাম, সে তার জন্য প্রার্থনা করতো আর তাকে ঈশ্বরের কাছে আত্মসমর্পণ করতে হত এবং তার সাথে যোগাযোগ স্থাপন করতে হত। ( গীতসংহিতা ৩৪: ৮) স্বর্গে আমি সাক্ষ্য দেওয়ার প্রতিজ্ঞা করি যে, কত জন ব্যক্তি তা লাভ করেছে বা অপরাধী হয়েছে । হেরে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏فَزَارَةُ بْنُ عَمْرٍو ‏ ‏أَخْبَرَنِي ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي عَمْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ آمَنَ بِاللَّهِ وَرَسُولِهِ وَأَقَامَ الصَّلَاةَ وَصَامَ رَمَضَانَ فَإِنَّ حَقًّا عَلَى اللَّهِ عَزَّ وَجَلَّ أَنْ يُدْخِلَهُ الْجَنَّةَ هَاجَرَ فِي سَبِيلِ اللَّهِ أَوْ جَلَسَ فِي أَرْضِهِ الَّتِي وُلِدَ فِيهَا قَالُوا يَا رَسُولَ اللَّهِ أَفَلَا نُنَبِّئُ النَّاسَ بِذَلِكَ قَالَ إِنَّ فِي الْجَنَّةِ مِائَةَ دَرَجَةٍ أَعَدَّهَا لِلْمُجَاهِدِينَ فِي سَبِيلِهِ مَا بَيْنَ كُلِّ دَرَجَتَيْنِ كَمَا بَيْنَ السَّمَاءِ وَالْأَرْضِ فَإِذَا سَأَلْتُمْ اللَّهَ عَزَّ وَجَلَّ فَسَلُوهُ الْفِرْدَوْسَ فَإِنَّهَا أَوْسَطُ الْجَنَّةِ وَأَعْلَى الْجَنَّةِ وَفَوْقَهُ عَرْشُ الرَّحْمَنِ عَزَّ وَجَلَّ وَمِنْهُ تَفَجَّرُ أَنْهَارُ الْجَنَّةِ ‏","","",""],[8120,8120,"","আমরা একটা পাখি নিয়ে কথা বলেছি যে আমাকে সুস্থ করার চেষ্টা করছে, ঈশ্বর তাকে আদেশ দিয়েছেন আর ঈশ্বরের কাছে আত্মসমর্পণ করবে, যদি ঈশ্বর আমাকে কথা দেন, আমাকে ঈশ্বর তা জানতে হবে। আমার বাবা বলেছিলেন যে, তিনি যদি আমাদের হত্যা করেন, তা হলে তিনি ঈশ্বরকে হত্যা করবেন ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏عَمْرٍو بْنِ قُهَيْدِ بْنِ مُطَرِّفٍ الْغِفَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ إِنْ عُدِيَ عَلَى مَالِي قَالَ فَانْشُدْ اللَّهَ قَالَ فَإِنْ أَبَوْا عَلَيَّ قَالَ انْشُدْ اللَّهَ قَالَ فَإِنْ أَبَوْا عَلَيَّ قَالَ فَانْشُدْ اللَّهَ قَالَ فَإِنْ أَبَوْا عَلَيَّ قَالَ ‏ ‏فَقَاتِلْ فَإِنْ قُتِلْتَ فَفِي الْجَنَّةِ وَإِنْ قَتَلْتَ فَفِي النَّارِ ‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ قُهَيْدٍ الْغِفَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[8121,8121,"","আমি আমার নাম আর বাবা আমার ভালবাসার কথা বলেছিলাম। তিনি বলেছিলেন, যদি যেতে হয় তাহলে তিনি ভালোর জন্য সেরা হবেন। হাঁটু গেড়ে বসলে আমি চলে যাব।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏شَكَا ‏ ‏أَصْحَابُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيْهِ مَشَقَّةَ السُّجُودِ عَلَيْهِمْ إِذَا تَفَرَّجُوا قَالَ اسْتَعِينُوا بِالرُّكَبِ ‏ ‏قَالَ ‏ ‏ابْنُ عَجْلَانَ ‏ ‏وَذَلِكَ أَنْ يَضَعَ مِرْفَقَهُ عَلَى رُكْبَتَيْهِ إِذَا أَطَالَ السُّجُودَ وَأَعْيَا ‏","","",""],[8122,8122,"","আমি আমার বাবা, আমার ভাই, একটি ছেলে খুঁজে পেতে চেষ্টা. আমি বলেছি আপনি দেখতে না যে ঈশ্বর আমাকে কিভাবে আমাকে একজন হাঙ্গর হিসেবে বর্ণনা করবেন যে তাদের ধরে রাখা হয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَلَمْ تَرَوْا كَيْفَ يَصْرِفُ اللَّهُ عَنِّي لَعْنَ ‏ ‏قُرَيْشٍ ‏ ‏وَشَتْمَهُمْ يَسُبُّونَ ‏ ‏مُذَمَّمًا ‏ ‏وَأَنَا ‏ ‏مُحَمَّدٌ ‏","","",""],[8123,8123,"","আমরা একটা ছেলের কথা বলেছিলাম যে শীঘ্রই আমার বাবাকে খুশি করবে, আমি ঈশ্বরের কাছে প্রার্থনা করব আর সে এটা ছেড়ে দেবে আর সে আগুনে আওয়াজ করবে না, স্বপ্নের বা পরের বার সে। ঈশ্বরের মৃত্যুর রাতে একজন ভাল দাসী হওয়ার নাম কখনো শুনি নি এবং একটি মহান জীবন বিশ্বাসঘাতকতা করে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ يَعْنِي ابْنَ عَجْلَانَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَجْتَمِعَانِ فِي النَّارِ اجْتِمَاعًا يَضُرُّ أَحَدَهُمَا مُسْلِمٌ قَتَلَ كَافِرًا ثُمَّ ‏ ‏سَدَّدَ ‏ ‏الْمُسْلِمُ ‏ ‏أَوْ ‏ ‏قَارَبَ ‏ ‏وَلَا يَجْتَمِعَانِ فِي جَوْفِ عَبْدٍ غُبَارٌ فِي سَبِيلِ اللَّهِ وَدُخَانُ جَهَنَّمَ وَلَا يَجْتَمِعَانِ فِي قَلْبِ عَبْدٍ الْإِيمَانُ ‏ ‏وَالشُّحُّ ‏","","",""],[8124,8124,"","ঈশ্বরের দোহাইর জন্য একটা উপহার তাকে আদেশ করে দিয়েছে আর সে বলেছে সে চলে গেছে। আমি বধির ছেলেগুলোকে নিয়ে এসেছি, যারা তাদের আঙুল হারিয়ে ফেলেছে। আমি তাকে বলি যে, আপনার ছেলে তার মন হারিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ هُرْمُزَ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏خَرَجَتْ امْرَأَتَانِ وَمَعَهُمَا صَبِيَّانِ فَعَدَا الذِّئْبُ عَلَى أَحَدِهِمَا فَأَخَذَتَا يَخْتَصِمَانِ فِي الصَّبِيِّ الْبَاقِي فَاخْتَصَمَتَا إِلَى ‏ ‏دَاوُدَ ‏ ‏فَقَضَى بِهِ لِلْكُبْرَى مِنْهُمَا فَمَرَّتَا عَلَى ‏ ‏سُلَيْمَانَ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ فَكَيْفَ أَمَرَكُمَا فَقَصَّتَا عَلَيْهِ الْقِصَّةَ فَقَالَ ائْتُونِي بِالسِّكِّينِ أَشُقُّ الْغُلَامَ بَيْنَكُمَا فَقَالَتْ الصُّغْرَى أَتَشُقُّهُ قَالَ نَعَمْ قَالَتْ لَا تَفْعَلْ حَظِّي مِنْهُ لَهَا فَقَالَ هُوَ ابْنُكِ فَقَضَى بِهِ لَهَا ‏","","",""],[8125,8125,"","আমি আমার ভাইকে এত খুশি করার জন্য আমার বাবাকে সাহায্য করার কথা বলেছিলাম, সে বলবে যে সে আমাকে বলেনি আমি তাকে বলিনি যে তার কিছু যাদুর কথা বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنِّي لَا أَقُولُ إِلَّا حَقًّا قَالَ بَعْضُ أَصْحَابِهِ فَإِنَّكَ تُدَاعِبُنَا يَا رَسُولَ اللَّهِ فَقَالَ إِنِّي لَا أَقُولُ إِلَّا حَقًّا ‏","","",""],[8126,8126,"","আমরা তার বাবা আর তার ছেলের কথা বলেছিলাম আমার বাবা দেবী হিসেবে কথা বলতে। সে যত বেশি তাঁকে ছেড়ে দেবে তত বেশি সে তার মৃত্যুর জন্য আত্মসমর্পণ করবে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَغَيْرِهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْأَكْثَرُونَ الْأَسْفَلُونَ يَوْمَ الْقِيَامَةِ إِلَّا مَنْ قَالَ هَكَذَا وَهَكَذَا ‏","","",""],[8127,8127,"","আমরা বাবার সঙ্গে তার বাবার কথা বলেছিলাম । কান, আমাকে বাকিদের দ্বারা প্রত্যাখ্যাত হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏الْعَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ النَّاسِ خَيْرٌ فَقَالَ أَنَا وَالَّذِينَ مَعِي ثُمَّ الَّذِينَ عَلَى ‏ ‏الْأَثَرِ ‏ ‏ثُمَّ الَّذِينَ عَلَى ‏ ‏الْأَثَرِ ‏ ‏ثُمَّ كَأَنَّهُ رَفَضَ مَنْ بَقِيَ ‏","","",""],[8128,8128,"","আমার ছেলে কুঁড়েঘরের কথা চিন্তা করে আমরা তার জন্য প্রার্থনা করেছি ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏الْقَعْقَاعِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَنْ يَزَالَ عَلَى هَذَا الْأَمْرِ ‏ ‏عِصَابَةٌ ‏ ‏عَلَى الْحَقِّ لَا يَضُرُّهُمْ مَنْ خَالَفَهُمْ حَتَّى يَأْتِيَهُمْ أَمْرُ اللَّهِ وَهُمْ عَلَى ذَلِكَ ‏","","",""],[8129,8129,"","আমরা বাবার সাথে কথা বলেছি তার বাবার ঈশ্বর এটা উদ্ধার করতে হবে আর সে তার ডানা আর আরেকটায় যাবে, কিন্তু সে অন্ধকারে থাকবে। তার রক্ত আছে, তারপর সে বেরিয়ে যাচ্ছে.","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ الذُّبَابَ فِي أَحَدِ جَنَاحَيْهِ دَاءٌ وَفِي الْآخَرِ شِفَاءٌ فَإِذَا وَقَعَ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْمِسْهُ فَإِنَّهُ يَتَّقِي بِالَّذِي فِيهِ الدَّاءُ ثُمَّ يُخْرِجُهُ ‏","","",""],[8130,8130,"","আমরা আমার বাবার সাথে কথা বলেছি যাতে তার বাবার সাথে এত সহজে যোগাযোগ করা যায়। সে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ صُفُوفِ الرِّجَالِ أَوَّلُهَا وَشَرُّهَا آخِرُهَا وَخَيْرُ صُفُوفِ النِّسَاءِ آخِرُهَا وَشَرُّهَا أَوَّلُهَا ‏","","",""],[8131,8131,"","বাবার সাথে আমার ভাইকে খুশি করার কথা বলছি, আমি বাবার কুমারীর কথা শুনতে চাই। সে বলবে, সে বলবে ঈশ্বরের কাছে আছে এবং তাকে এটা ছেড়ে দিতে হবে এবং সে তোমাকে যেতে দেবে না চল, আল্লাহ না চাইলেই প্রার্থনা করতে পারেন না।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَتَوَضَّأُ أَحَدُكُمْ فَيُحْسِنُ وُضُوءَهُ وَيُسْبِغُهُ ثُمَّ يَأْتِي الْمَسْجِدَ لَا يُرِيدُ إِلَّا الصَّلَاةَ فِيهِ إِلَّا ‏ ‏تَبَشْبَشَ ‏ ‏اللَّهُ عَزَّ وَجَلَّ بِهِ كَمَا ‏ ‏يَتَبَشْبَشُ ‏ ‏أَهْلُ الْغَائِبِ بِطَلْعَتِهِ ‏","","",""],[8132,8132,"","ঈশ্বর তাকে আদেশ দিয়েছেন এবং তাদের কাছে বলবে যে, আমি পতাকা না জিততে তোমার পতাকাকে অভিবাদন করব না । আর পৃথিবীর শেষ প্রান্তে, তুমি শুনতে শুনতেও আহুতের মতো লাগে না","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عَبَّادِ بْنِ أَبِي سَعِيدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْأَرْبَعِ مِنْ عِلْمٍ لَا يَنْفَعُ وَمِنْ قَلْبٍ لَا يَخْشَعُ وَمِنْ نَفْسٍ لَا تَشْبَعُ وَمِنْ دُعَاءٍ لَا يُسْمَعُ ‏","","",""],[8133,8133,"","বাবা একজন পলাতক বাবা হিসেবে আমার সাথে কথা বলেছিলাম, সে আমাকে তার বাবার সাথে সাহায্য করতে বলেছে। সে বলতে চায়, সে এক শান্তিপূর্ণ মহিলাকে সমাধান করবে না। মুক্ত।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَحِلُّ لِامْرَأَةٍ مُسْلِمَةٍ تُسَافِرُ لَيْلَةً إِلَّا وَمَعَهَا رَجُلٌ ذُو حُرْمَةٍ مِنْهَا ‏","","",""],[8134,8134,"","তিনি ঈশ্বরের কাছে তার দেহ স্থির করেছিলেন এবং নিজের ওপর জোর দিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ أَعَزَّ جُنْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الْأَحْزَابَ وَحْدَهُ فَلَا شَيْءَ بَعْدَهُ ‏","","",""],[8135,8135,"","বাবা ঈশ্বরের কাছে প্রার্থনা করার জন্য একটা উপহার আর তিনি আমার বাবার জন্য উত্তম প্রভু বলে বলবেন । আর আমি যখন মারা যাই অথবা ঈশ্বর আমার চেয়ে আরও বেশি কিছু অর্জন করেছেন, তখন আমি তাঁর কাছে আরও বেশি কিছু চাইতে পারি ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ الْأَنْبِيَاءِ نَبِيٌّ إِلَّا وَقَدْ أُعْطِيَ مِنْ الْآيَاتِ مَا مِثْلُهُ آمَنَ عَلَيْهِ الْبَشَرُ وَإِنَّمَا كَانَ الَّذِي أُوتِيتُ وَحْيًا أَوْحَاهُ اللَّهُ عَزَّ وَجَلَّ إِلَيَّ وَأَرْجُو أَنْ أَكُونَ أَكْثَرَهُمْ تَبَعًا يَوْمَ الْقِيَامَةِ ‏","","",""],[8136,8136,"","আমি ঈশ্বরের কাছে প্রার্থনা করেছি তার জন্য প্রার্থনা করতে, আর আমি বলতে চাই যে ঈশ্বর ঈশ্বরের কাছে জয় করেছেন, তিনি আমাকে ভালবাসেন আর বেনের শ্বাস বন্ধ করে দিয়েছেন জেন জেন.","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ الْهَادِ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ ‏ ‏إِنَّ عَبْدِي الْمُؤْمِنَ عِنْدِي بِمَنْزِلَةِ كُلِّ خَيْرٍ يَحْمَدُنِي وَأَنَا أَنْزِعُ نَفْسَهُ مِنْ بَيْنِ جَنْبَيْهِ ‏","","",""],[8137,8137,"","ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং প্রভু ঈশ্বরের কাছে আমি আশ্রয় নিচ্ছি এবং আমি ঈশ্বরের প্রেমে থাকব তার সাথে দুনিয়ায়।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَاللَّهِ ‏ ‏إِنِّي لَأَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ فِي الْيَوْمِ أَكْثَرَ مِنْ سَبْعِينَ مَرَّةً ‏","","",""],[8138,8138,"","আমরা সুখী ছেলেরা আরও ভাল কিছু পাওয়ার চেষ্টা করার বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ مَيْسَرَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ الْبَصْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اسْتَمَعَ إِلَى آيَةٍ مِنْ كِتَابِ اللَّهِ تَعَالَى كُتِبَ لَهُ حَسَنَةٌ مُضَاعَفَةٌ وَمَنْ تَلَاهَا كَانَتْ لَهُ نُورًا يَوْمَ الْقِيَامَةِ ‏","","",""],[8139,8139,"","বাবা খুশি হয়ে কথা বলেছিল আর সে বাবাকে গুলি করার ব্যাপারে কথা বলেছিল, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর সে উজ্জ্বল সকালে ঘুমায় ঘুমালে আত্মসমর্পণ করবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عِسْلُ بْنُ سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا طَلَعَ النَّجْمُ ذَا صَبَاحٍ رُفِعَتْ ‏ ‏الْعَاهَةُ ‏","","",""],[8140,8140,"","আমরা আমাদের সাথে আনন্দের সাথে বাবার কথা বলেছি আর আমার ছেলেকে ঘোড়া দেওয়ার ব্যাপারে উত্তেজিত হয়ে তিনি আমার কাছে প্রার্থনা করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏وَحَمَّادٌ ‏ ‏عَنْ ‏ ‏عِسْلٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏السَّدْلِ ‏ ‏يَعْنِي فِي الصَّلَاةِ ‏","","",""],[8141,8141,"","ঈশ্বরের ওপর জয়ী হওয়ার বিষয়ে আমরা কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْفَضْلِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ مِنْ تَلْبِيَةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبَّيْكَ إِلَهَ الْحَقِّ ‏","","",""],[8142,8142,"","আমরা আমার বাবার সম্পর্কে কথা বলেছিলাম, তিনি একবার আকাশ থেকে পণ্ডিতদের কিছু করার কথা বলেছিলেন... ...সে বলেছিল এটা সেলাই করতে.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَرَّ رَجُلٌ مِنْ الْمُسْلِمِينَ ‏ ‏بِجِذْلِ ‏ ‏شَوْكٍ فِي الطَّرِيقِ فَقَالَ ‏ ‏لَأُمِيطَنَّ ‏ ‏هَذَا الشَّوْكَ عَنْ الطَّرِيقِ أَنْ لَا ‏ ‏يَعْقِرَ ‏ ‏رَجُلًا مُسْلِمًا قَالَ فَغُفِرَ لَهُ ‏","","",""],[8143,8143,"","সে বলেছিল যে তার এই মোটাতা নিয়ে একটা অভিশাপ আছে... ...যে সে এই কথা বলেছে... ...যদি আমাকে করতে বলা হয়, সে জানে না তারা কিসের পিছনে লেগে আছে।","‏ ‏قَالَ ‏ ‏حَدَّثَنَاه ‏ ‏عَفَّانُ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَكَلَ أَحَدُكُمْ فَلْيَلْعَقَنَّ أَصَابِعَهُ فَإِنَّهُ لَا يَدْرِي فِي أَيَّتِهِنَّ الْبَرَكَةُ ‏","","",""],[8144,8144,"","আমার বাবা আমার ছেলেকে ভালোবাসেন বলে আমি ঈশ্বরকে ভালবাসি । তোমারটা।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَحَبَّ اللَّهُ عَبْدًا دَعَا ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَ إِنِّي قَدْ أَحْبَبْتُ فُلَانًا فَأَحِبَّهُ قَالَ فَيُحِبُّهُ ‏ ‏جِبْرِيلُ ‏ ‏قَالَ ثُمَّ يُنَادِي فِي السَّمَاءِ إِنَّ اللَّهَ قَدْ أَحَبَّ فُلَانًا فَأَحِبُّوهُ قَالَ فَيُحِبُّونَهُ قَالَ ثُمَّ يَضَعُ اللَّهُ لَهُ الْقَبُولَ فِي الْأَرْضِ فَإِذَا أَبْغَضَ فَمِثْلُ ذَلِكَ ‏","","",""],[8145,8145,"","তিনি বলেছিলেন যে, তার উপস্থিতি এবং এইরকম বিস্ময়কর জীবনের প্রতি শ্রদ্ধা থেকে সেই দিন শুরু হয়ে যায় ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فُتِحَ الْيَوْمَ مِنْ ‏ ‏رَدْمِ ‏ ‏يَأْجُوجَ ‏ ‏وَمَأْجُوجَ ‏ ‏مِثْلُ هَذَا وَعَقَدَ ‏ ‏وُهَيْبٌ ‏ ‏تِسْعِينَ ‏","","",""],[8146,8146,"","আমাদের কথাবার্তার কথা বলেছিলাম আর এটা আমার বাবাকে নিয়ে ছিল ভাঙ্গার চেষ্টা করার ব্যাপারে। ঈশ্বর তাকে আদেশ দিয়েছেন, আর তিনি তোমাকে কখনই এত মহান হতে নিষেধ করেছেন না। ছেড়ে দাও, নাহলে ভগবানের কথা শুনবে, যাকে বলবে, হয়তো তুমি বলবে, তারা অনেক প্রার্থনা করেছে, তারা একটা হালেলুজার প্রার্থনা করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُصْعَبُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّمَا الْإِمَامُ ‏ ‏لِيُؤْتَمَّ ‏ ‏بِهِ فَإِذَا كَبَّرَ فَكَبِّرُوا وَلَا تُكَبِّرُوا حَتَّى يُكَبِّرَ وَإِذَا رَكَعَ فَارْكَعُوا وَلَا تَرْكَعُوا حَتَّى يَرْكَعَ وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا رَبَّنَا وَلَكَ الْحَمْدُ وَإِذَا سَجَدَ فَاسْجُدُوا وَلَا تَسْجُدُوا حَتَّى يَسْجُدَ وَإِنْ صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا أَجْمَعُونَ ‏","","",""],[8147,8147,"","আমরা আমাদের আলোচনা আর বাবা ঈশ্বরের প্রতি ঈর্ষা প্রকাশ করেছেন, সে বলবে আমরা হচ্ছি ডার্ক ওয়ানের শেষ মৃত্যু জন্য দায়ী। ( আদিপুস্তক ৬: ১ - ৪) প্রতি সাত দিনে তিনি তার মস্তক ও তার দেহের সমস্ত শান্তি দূর করেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نَحْنُ الْآخِرُونَ السَّابِقُونَ يَوْمَ الْقِيَامَةِ ‏ ‏بَيْدَ ‏ ‏أَنَّ كُلَّ أُمَّةٍ أُوتُوا الْكِتَابَ ‏ ‏مِنْ قَبْلِنَا وَأُوتِينَاهُ مِنْ بَعْدِهِمْ فَهَذَا الْيَوْمُ الَّذِي اخْتَلَفُوا فِيهِ فَهَدَانَا اللَّهُ عَزَّ وَجَلَّ لَهُ فَغَدًا ‏ ‏لِلْيَهُودِ ‏ ‏وَبَعْدَ غَدٍ ‏ ‏لِلنَّصَارَى ‏ ‏فَسَكَتَ فَقَالَ حَقُّ اللَّهِ عَلَى كُلِّ مُسْلِمٍ أَنْ يَغْتَسِلَ فِي كُلِّ سَبْعَةِ أَيَّامٍ يَغْسِلُ رَأْسَهُ وَجَسَدَهُ ‏","","",""],[8148,8148,"","আমরা আমাদের আলোচনা নিয়ে কথা বলেছি এবং বাবা ঈশ্বরের কাছে প্রার্থনা করেছেন যেন ঈশ্বর তা বলতে ইচ্ছুক থাকেন এবং আপনি তা চিহ্নিত করতে পারেন না এবং আপনি থাকুন না। আপনি চলমান থাকুন এবং একটি মানুষ নন। ঈশ্বরের প্রতি বিশ্বাসঘাতক।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِيَّاكُمْ وَالظَّنَّ فَإِنَّ الظَّنَّ أَكْذَبُ الْحَدِيثِ وَلَا ‏ ‏تَجَسَّسُوا ‏ ‏وَلَا ‏ ‏تَحَسَّسُوا ‏ ‏وَلَا ‏ ‏تَبَاغَضُوا ‏ ‏وَلَا ‏ ‏تَدَابَرُوا ‏ ‏وَلَا تَنَافَسُوا وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا ‏","","",""],[8149,8149,"","ঈশ্বর তাকে তার কাছে সমর্পণ করার জন্য অনুরোধ করেছেন, যিনি মনে করেছিলেন যে, আমি হয়তো ঈশ্বর ও আমি কে ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ وَمَنْ أَطَاعَ الْأَمِيرَ فَقَدْ أَطَاعَنِي ‏","","",""],[8150,8150,"","আমি যখন একটা ঘোড়ার ছেলে ছিলাম, তখন একদিন আমি কথা বলেছিলাম, যে আমার কাজ করার জন্য প্রত্যেকবার একটা রাজধানী গড়ে তুলেছিল । অতএব , আপনি পালনকর ্ তার মহান প ্ রশংসাসহ এক ব ্ যক ্ তি ,","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ يَعْنِي ابْنَ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ كُلَيْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏ذَكَرَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُؤْيَا الرَّجُلِ الْمُسْلِمِ جُزْءٌ مِنْ سَبْعِينَ جُزْءًا مِنْ النُّبُوَّةِ ‏","","",""],[8151,8151,"","আমরা তোমার চাচার ব্যাপারে কথা বলেছিলাম, আমার বাবা আল্লাহ্‌র আশীর্বাদ কামনা করছি, আমি শুনেছি ঈশ্বরের দয়া যেন আপনার অনুগ্রহের উপর থাকে। রাতের শুকনো আবহাওয়ায়, আমি বরং খুব দ্রুত তোমার সাথে দেখা করতে চাই। মহান ঈশ্বরের গৌরব তুমি এটাকে মুক্ত বলে অভিহিত করো।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْتَشِرِ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَفْضَلُ الصَّلَاةِ بَعْدَ الْمَفْرُوضَةِ صَلَاةٌ فِي جَوْفِ اللَّيْلِ وَأَفْضَلُ الصِّيَامِ بَعْدَ شَهْرِ رَمَضَانَ شَهْرُ اللَّهِ الَّذِي تَدْعُونَهُ الْمُحَرَّمَ ‏","","",""],[8152,8152,"","একদিন আমরা একে অপরের রাজধানীর কথা বলেছিলাম, আমার বাবা বলেছিলেন, তিনি কখনো শোনেননি। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমার নিজের ছেলের ঘুমের মধ্যে আমার দৃষ্টি তুলে ধরেছেন। তিনি তার ছেলের সঙ্গে কথা বলেছিলেন, তাকে হয়তো তাকে বলতে বলেছিলেন যে ঈশ্বর তাকে বলেছিলেন এবং তিনি তার জায়গায় কথা বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ كُلَيْبٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّهِ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي فَإِنَّ الشَّيْطَانَ لَا يَتَمَثَّلُ بِي ‏ ‏قَالَ ‏ ‏عَاصِمٌ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏فَحَدَّثَنِيهِ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَأَخْبَرْتُهُ أَنِّي قَدْ رَأَيْتُهُ قَالَ رَأَيْتَهُ قُلْتُ إِي وَاللَّهِ لَقَدْ رَأَيْتُهُ قَالَ فَذَكَرْتُ ‏ ‏الْحَسَنَ بْنَ عَلِيٍّ ‏ ‏قَالَ ‏ ‏إِنِّي وَاللَّهِ قَدْ ذَكَرْتُهُ وَنَعَتُّهُ فِي مِشْيَتِهِ قَالَ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏إِنَّهُ كَانَ يُشْبِهُهُ ‏","","",""],[8153,8153,"","আমি আমার বাবাকে বলেছিলেন যে, বাবা খুশি হবেন । ভুলে যাও, সে বলবে আমি যদি তোমাকে ওর সাহস থেকে নিয়ন্ত্রণ করি... ...তাহলে তাকে যেতে হবে.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ أَبِي جَالِسًا وَعِنْدَهُ غُلَامٌ فَقَامَ الْغُلَامُ فَقَعَدْتُ فِي مَقْعَدِ الْغُلَامِ ‏ ‏فَقَالَ ‏ ‏لِي ‏ ‏أَبِي ‏ ‏قُمْ عَنْ مَقْعَدِهِ ‏ ‏إِنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَنْبَأَنَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَامَ أَحَدُكُمْ مِنْ مَجْلِسِهِ فَرَجَعَ إِلَيْهِ فَهُوَ أَحَقُّ بِهِ ‏ ‏غَيْرَ أَنَّ ‏ ‏سُهَيْلًا ‏ ‏قَالَ ‏ ‏لَمَّا أَقَامَنِي تَقَاصَرْتُ فِي نَفْسِي ‏","","",""],[8154,8154,"","আমরা কথা বলেছিলাম একটা জীবন আছে। আমার বাবা প্রভু ও ঈশ্বর তার পালনকর্‌কে রক্ষা করেছেন। তিনি পারেন না।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏عَجْلَانَ أَبِي مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِلْمَمْلُوكِ طَعَامُهُ وَكِسْوَتُهُ وَلَا يُكَلَّفُ مِنْ الْعَمَلِ مَا لَا يُطِيقُ ‏","","",""],[8155,8155,"","আমরা আমার বাবার কথা বলেছিলাম আমার বাবার কথা যেন একজন উৎপীড়ক হয়, ঈশ্বর তা উদ্ধার করতে পারেন আর তিনি বলবেন যে বছর সে কন্ট্রোলে থাকবে না.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏السَّنَةَ ‏ ‏لَيْسَ بِأَنْ لَا يَكُونَ فِيهَا مَطَرٌ وَلَكِنَّ ‏ ‏السَّنَةَ ‏ ‏أَنْ تُمْطِرَ السَّمَاءُ وَلَا تُنْبِتَ الْأَرْضُ ‏","","",""],[8156,8156,"","আমরা আমাদের নিজেদের বাজি রক্ষা করার চেষ্টা করেছি, এই বলে যে আমরা একটা ছেলে দ্বারা বাপ্তাইজিত হব। আমার বাবা উপহার আর তিনি আমার বাবার রাজার সাথে দেখা করতে পারবেন। তিনি একজন মই আর একটা শোকাপন্ন হয়ে যাবেন। বন্য আত্মার হৃদয় থেকে যে কারো কথা শোনা যাবে না, হামাদ বলেছেন, তাদের একজন মুরগির ওপর বসে বলেছেন যে, আরেকজনকে ধরা উচিত।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏صَفْوَانَ يَعْنِي ابْنَ سُلَيْمٍ ‏ ‏عَنِ ‏ ‏الْقَعْقَاعِ بْنِ اللَّجْلَاجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَسُهَيْلٍ ‏ ‏عَنِ ‏ ‏الْقَعْقَاعِ بْنِ اللَّجْلَاجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَجْتَمِعُ شُحٌّ وَإِيمَانٌ فِي قَلْبِ رَجُلٍ وَلَا يَجْتَمِعُ غُبَارٌ فِي سَبِيلِ اللَّهِ وَدُخَانُ جَهَنَّمَ فِي وَجْهِ عَبْدٍ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏وَقَالَ أَحَدُهُمَا ‏ ‏الْقَعْقَاعُ بْنُ اللَّجْلَاجِ ‏ ‏وَقَالَ الْآخَرُ ‏ ‏اللَّجْلَاجُ بْنُ الْقَعْقَاعِ ‏","","",""],[8157,8157,"","আমি আমার বাবার কাছে একটা স্বপ্নের বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنْ كَانَ فِي شَيْءٍ مِمَّا ‏ ‏تَدَاوَوْنَ بِهِ خَيْرٌ فَفِي ‏ ‏الْحِجَامَةِ ‏","","",""],[8158,8158,"","ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং তিনি বলেছিলেন যে, যদি লোকেরা এমনটা করত, তাহলে তিনি তা করতেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَالَ الرَّجُلُ قَدْ هَلَكَ النَّاسُ فَهُوَ أَهْلَكُهُمْ ‏","","",""],[8159,8159,"","আমরা আমাদের আলোচনা নিয়ে কথা বলেছি এবং এটা ছিল জাীরের প্রতি আমার ভালোবাসা। আমি ঈশ্বরের সাথে যুদ্ধ করছি যে তিনি ঈশ্বরের কাছে শপথ গ্রহণ করবেন, ঈশ্বরের কাছে ঈশ্বরের কাছে ঈশ্বরের কাছে, ঈশ্বরের কাছে ঈশ্বরের কাছে, ঈশ্বরের কাছে ঈশ্বরের কাছে। ঈশ্বর তাঁর সাথে কিছু একটাও শেয়ার করেন না এবং সংঘর্ষের সাথে তার সংযোগ মূল্যায়ন করেন না এবং আত্মার আত্মার আত্মার পরাজয়ের জন্য আর প ্ রত ্ যেক সত ্ ত ্ বা জানে যে তার অন ্ তরের আ ‌ ত ্ মার জন ্ য সাক ্ ষ ্ য দেওয়া হবে , আমি আর এটা করতে পারবো না, আমি এটা হারাব, একজন পাগল যে এটা দেখছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ وَهُوَ أَبُو حَيَّانَ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ أَعْرَابِيًّا جَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏دُلَّنِي عَلَى عَمَلٍ إِذَا عَمِلْتُهُ دَخَلْتُ الْجَنَّةَ قَالَ تَعْبُدُ اللَّهَ لَا تُشْرِكُ بِهِ شَيْئًا ‏ ‏وَتُقِيمُ الصَّلَاةَ الْمَكْتُوبَةَ وَتُؤَدِّي الزَّكَاةَ الْمَفْرُوضَةَ وَتَصُومُ رَمَضَانَ قَالَ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ لَا أَزِيدُ عَلَى هَذَا شَيْئًا أَبَدًا وَلَا أَنْقُصُ مِنْهُ فَلَمَّا ‏ ‏وَلَّى ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَرَّهُ أَنْ يَنْظُرَ إِلَى رَجُلٍ مِنْ أَهْلِ الْجَنَّةِ فَلْيَنْظُرْ إِلَى هَذَا ‏","","",""],[8160,8160,"","আমি ঈশ্বরের কাছে প্রার্থনা করছি, আমি এটা সব ছেড়ে দেব, শুভদিন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَصْبِرُ أَحَدٌ عَلَى ‏ ‏لَأْوَاءِ ‏ ‏الْمَدِينَةِ ‏ ‏وَجَهْدِهَا إِلَّا كُنْتُ لَهُ شَفِيعًا ‏ ‏أَوْ شَهِيدًا ‏ ‏يَوْمَ الْقِيَامَةِ ‏","","",""],[8161,8161,"","আমরা আমার ভাইয়ের স্বপ্ন নিয়ে কথা বলেছিলাম, ঈশ্বরের কাছে প্রার্থনা করতে বলেছেন, যেন তিনি এমন কিছু উদ্ধার করতে পারেন যা তাকে ভালোবাসার সাথে করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْكُمْ بِهَذِهِ الْحَبَّةِ السَّوْدَاءِ فَإِنَّ فِيهَا شِفَاءً مِنْ كُلِّ شَيْءٍ ‏","","",""],[8162,8162,"","একদিন আমরা আমার বাবাকে বলতে চেয়েছিলাম যে সে ঈশ্বরের কাছে প্রার্থনা করছে আর তার দৃষ্টিতে সকল পাপই সে তুলে ধরছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَاصِمُ بْنُ كُلَيْبٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ خُطْبَةٍ لَيْسَ فِيهَا شَهَادَةٌ كَالْيَدِ ‏ ‏الْجَذْمَاءِ ‏","","",""],[8163,8163,"","আমরা আমাদের ছেলেকে উড়তে সাহায্য করেছি, তিনি বলেছিলেন, আমরা আমাদের ভালোবাসার জন্য অনেক কিছু করেছি। আমার বাবা ঈশ্বরের কাছে প্রার্থনা করেছেন, তিনি প্রভু এবং ঈশ্বর দ্বারা রক্ষা পাবেন। ( ২ করি.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ الْعَطَّارُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُؤْمِنُ يَغَارُ وَاللَّهُ يَغَارُ وَمِنْ غَيْرَةِ اللَّهِ أَنْ يَأْتِيَ الْمُؤْمِنُ شَيْئًا حَرَّمَ اللَّهُ ‏","","",""],[8164,8164,"","তিনি বলেন যে, এটা এমন এক গাছ, যা আগুনকে আঘাত করে, যে কিনা রাস্তার ওপর দিয়ে ফেলে দিয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَتْ شَجَرَةٌ تُؤْذِي أَهْلَ الطَّرِيقِ فَقَطَعَهَا رَجُلٌ فَنَحَّاهَا عَنْ الطَّرِيقِ فَدَخَلَ الْجَنَّةَ ‏","","",""],[8165,8165,"","আমরা আমার ভালবাসার ব্যাপারে বাবার বাপ্তিস্মের কথা বলেছিলাম, আমার ভালবাসা হলো দেবীর মত, ঈশ্বর তাকে উদ্ধার করতে হবে আর তিনি তার নাম রাখার আগেই স্বর্গের প্রভুকে দেখতে পাবেন তার নাম","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَدْخُلُ فُقَرَاءُ الْمُسْلِمِينَ الْجَنَّةَ قَبْلَ أَغْنِيَائِهِمْ بِنِصْفِ يَوْمٍ وَهُوَ خَمْسُ مِائَةِ عَامٍ ‏","","",""],[8166,8166,"","ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তাঁকে আত্মসমর্পণ করার জন্য আমি যা করব, তা - ই করব, যেমনটা আপনাকে আপনার ওপর গণনা করতে হবে ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏مَنْ ‏ ‏سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ابْنَ ‏ ‏آدَمَ ‏ ‏اعْمَلْ كَأَنَّكَ تُرَى وَعُدَّ نَفْسَكَ مَعَ الْمَوْتَى وَإِيَّاكَ وَدَعْوَةَ الْمَظْلُومِ ‏","","",""],[8167,8167,"","আমি আমার সঙ্গে সঙ্গে যাওয়ার চেষ্টা করে যে - বাপ্তিস্মের কথা বলেছিলাম, তা আমার সঙ্গে সঙ্গে যাওয়ার চেষ্টা করে । এক ঘন্টা আগে, কয়েক বছর আগে... ...তোমার প্রার্থনার আলো এসে... ...এবং পরিকল্পনাটা এসেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْمَلَائِكَةَ يَوْمَ الْجُمُعَةِ عَلَى أَبْوَابِ الْمَسَاجِدِ يَكْتُبُونَ النَّاسَ عَلَى مَنَازِلِهِمْ جَاءَ فُلَانٌ مِنْ سَاعَةِ كَذَا جَاءَ فُلَانٌ مِنْ سَاعَةِ كَذَا جَاءَ فُلَانٌ وَالْإِمَامُ يَخْطُبُ جَاءَ فُلَانٌ فَأَدْرَكَ الصَّلَاةَ وَلَمْ يُدْرِكْ الْجُمُعَةَ ‏ ‏إِذَا لَمْ يُدْرِكْ الْخُطْبَةَ ‏","","",""],[8168,8168,"","আমরা একটি বাপ্তিস্মের পুত্র হিসেবে একটি ছেলেকে পরিণত করার চেষ্টা করেছি যে আমাকে সাহায্য করার জন্য আমার কাছে কখনো ঘটেছে, লর্ড তার জন্য প্রার্থনা এবং আত্মসমর্পণ আবার ক্ষমা প্রার্থনা করেন আর আবারও শহরের খুনিরা ফিরে আসে শহরে, আরো দুটো সাত বার যাবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَدْخُلُ أَهْلُ الْجَنَّةِ الْجَنَّةَ ‏ ‏مُرْدًا ‏ ‏بِيضًا ‏ ‏جِعَادًا ‏ ‏مُكَحَّلِينَ أَبْنَاءَ ثَلَاثٍ وَثَلَاثِينَ عَلَى خَلْقِ ‏ ‏آدَمَ ‏ ‏سَبْعُونَ ذِرَاعًا فِي سَبْعَةِ أَذْرُعٍ ‏","","",""],[8169,8169,"","আমরা একজন যাজকের সঙ্গে কথা বলেছিলাম, যিনি আমার প্রভুর প্রতি ভালবাসা দেখাতে পছন্দ করতেন । ''আর যে কেউ আমার কথা শুনবে ও আমি ভয় করি, সে তো হবেই, আর আমি হবাব। সেই ব্যক্তি যিনি আপনার রাজা হবেন, তিনি হবেন সেই ব্যক্তি, যিনি আপনার রাজা ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏وَحَبِيبٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏فِي كُلِّ صَلَاةٍ يُقْرَأُ فَمَا أَسْمَعَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْمَعْنَاكُمْ وَمَا أَخْفَى عَلَيْنَا أَخْفَيْنَا عَلَيْكُمْ ‏","","",""],[8170,8170,"","আমি আমার বাবার সঙ্গে কথা বলেছিলাম । সূর্য, তারা সমৃদ্ধ এবং পুরুষ পোশাক পরে এবং তারা হেঁটে যায় এবং বলে অথবা মিথ্যা বলে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِكُلِّ بَنِي ‏ ‏آدَمَ ‏ ‏حَظٌّ مِنْ الزِّنَا فَالْعَيْنَانِ تَزْنِيَانِ وَزِنَاهُمَا النَّظَرُ وَالْيَدَانِ تَزْنِيَانِ وَزِنَاهُمَا الْبَطْشُ وَالرِّجْلَانِ يَزْنِيَانِ وَزِنَاهُمَا الْمَشْيُ وَالْفَمُ يَزْنِي وَزِنَاهُ الْقُبَلُ وَالْقَلْبُ ‏ ‏يَهْوَى ‏ ‏وَيَتَمَنَّى وَالْفَرْجُ يُصَدِّقُ ذَلِكَ أَوْ يُكَذِّبُهُ ‏","","",""],[8171,8171,"","আমি আমার বাবার বাপ্তিস্মের কথা বলেছিলাম, আমার ভালবাসা হচ্ছে দেবী, ঈশ্বর তাকে আদেশ দিয়েছেন এবং তাকে পরাজিত করার জন্য ঈশ্বরের অন্ত্যেষ্টিক্রিয়ার আয়োজন করেছেন। তারপর তিনি তার সাথে যোগ দেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّتْ بِهِ جَنَازَةُ يَهُودِيٍّ فَقَامَ فَقِيلَ لَهُ يَا رَسُولَ اللَّهِ إِنَّهَا جَنَازَةُ يَهُودِيٍّ فَقَالَ ‏ ‏إِنَّ لِلْمَوْتِ ‏ ‏فَزَعًا ‏","","",""],[8172,8172,"","আমরা আমার বাবার কথা বলেছিলাম আমার ছেলের এত মিষ্টি হওয়া নিয়ে। সে বলবে তুমি চাও না তুমি তার কুকুরের মত তোমার পূর্ণনন করুক।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَصْحَبُ الْمَلَائِكَةُ رُفْقَةً فِيهَا كَلْبٌ أَوْ جَرَسٌ ‏","","",""],[8173,8173,"","আমি আমার বাবার সঙ্গে আমার পরিবারের কথা বলেছিলাম, দয়া বলে কথা বলায় ঈশ্বর আপনাকে আপনার কাছ থেকে আত্মসমর্পণ করবেন এবং বলেন যে, তিনি রক্ষা পাবেন না ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْكُمْ مِنْ أَحَدٍ ‏ ‏يُنَجِّيهِ عَمَلُهُ قَالُوا وَلَا أَنْتَ يَا رَسُولَ اللَّهِ قَالَ وَلَا أَنَا إِلَّا أَنْ ‏ ‏يَتَغَمَّدَنِيَ ‏ ‏اللَّهُ مِنْهُ بِرَحْمَةٍ ‏","","",""],[8174,8174,"","আমরা আমার ছেলের বাপ্তিস্মের কথা বলেছিলাম, আমার ভালোবাসা হচ্ছে দেবীর মত, ঈশ্বর তাকে উদ্ধার করতে হবে আর সে আমাকে আমার হাতে অন্যদের সাথে বিশ্বাসঘাতকতা করতে হবে। মশীহ.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ فِيمَا يَرَى النَّائِمُ كَأَنَّ فِي يَدِي سِوَارَيْنِ فَنَفَخْتُهُمَا فَرُفِعَا ‏ ‏فَأَوَّلْتُ ‏ ‏أَنَّ أَحَدَهُمَا ‏ ‏مُسَيْلِمَةُ ‏","","",""],[8175,8175,"","আমরা আমাদের কথা বলেছিলাম, কীভাবে বিষে সাহায্য করতে হয় ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ ‏ ‏مَعْمَرٌ ‏ ‏حَدَّثَنَا عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا بَاتَ أَحَدُكُمْ وَفِي يَدِهِ ‏ ‏غَمَرٌ ‏ ‏فَأَصَابَهُ شَيْءٌ فَلَا يَلُومَنَّ إِلَّا نَفْسَهُ ‏","","",""],[8176,8176,"","তিনি বলেছেন, তিনি ঈশ্বরকে দেখে খুশি হবেন না। আর এমন একজন মানুষ যিনি তার রোষ্টে তার মহিলাকে জড়ো করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ مُخَلَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَنْظُرُ اللَّهُ عَزَّ وَجَلَّ إِلَى رَجُلٍ جَامَعَ امْرَأَتَهُ فِي ‏ ‏دُبُرِهَا ‏","","",""],[8177,8177,"","আমরা আমাদের বাপ্তিস্মকে আমার ভালোবাসার জন্য ঈশ্বরকে দেয়ার মাধ্যমে সংরক্ষণ করার চেষ্টা করেছি। লর্ড তার পতাকা আদেশ দিয়েছেন এবং সৃষ্টিকর্তাকে তার কাছে সমর্পণ করবেন। জীবনের জন্য লড়াই করা।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ سُئِلَ عَنْ عِلْمٍ فَكَتَمَهُ ‏ ‏أَلْجَمَهُ ‏ ‏اللَّهُ عَزَّ وَجَلَّ ‏ ‏بِلِجَامٍ ‏ ‏مِنْ نَارٍ يَوْمَ الْقِيَامَةِ ‏","","",""],[8178,8178,"","আমরা বাবার কাছে ঈশ্বরের অনুগ্রহের দ্বারা আমার বাবাকে রক্ষা করার চেষ্টা সম্বন্ধে কথা বলেছিলাম । রাত-দিন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْضَلُ الصِّيَامِ بَعْدَ رَمَضَانَ شَهْرُ اللَّهِ الْمُحَرَّمُ وَأَفْضَلُ الصَّلَاةِ بَعْدَ الْفَرِيضَةِ ‏ ‏أَوْ الْفَرْضِ ‏ ‏صَلَاةُ اللَّيْلِ ‏","","",""],[8179,8179,"","আমরা যখন আমার ছেলেকে হারিয়ে যেতে দেখে ক্লান্ত হয়ে পড়া সম্বন্ধে কথা বলেছিলাম, তখন আমরা মোশির সঙ্গে কথা বলেছিলাম । তার হাতের বিরুদ্ধে যুদ্ধ করতে ইচ্ছুক, যদি তুমি মারা যাও আর আমি তাকে আগুনে পুড়িয়ে দেবো, তাহলে তুমি আমাকে ভিতরে নিয়ে যাবে... ঘোড়ার পিঠে ঘোড়া আছে যেটা তাদের কাছে গুজবের পরে যায় না।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏ابْنِ هُرْمُزَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا دَخَلَ أَهْلُ الْجَنَّةِ الْجَنَّةَ وَأَهْلُ النَّارِ النَّارَ نَادَى مُنَادٍ يَا أَهْلَ الْجَنَّةِ خُلُودًا فَلَا مَوْتَ فِيهِ وَيَا أَهْلَ النَّارِ خُلُودًا فَلَا مَوْتَ فِيهِ ‏ ‏قَالَ ‏ ‏وَذَكَرَ ‏ ‏لِي ‏ ‏خَالِدُ بْنُ زَيْدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا الزُّبَيْرِ ‏ ‏يَذْكُرُ مِثْلَهُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏وَعُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏إِلَّا أَنَّهُ يُحَدِّثُ عَنْهُمَا أَنَّ ذَلِكَ بَعْدَ الشَّفَاعَاتِ وَمَنْ يُخْرَجُ مِنْ النَّارِ ‏","","",""],[8180,8180,"","বাবা যখন আমার ঈশ্বরের কাছে প্রার্থনা করতো, তখন আমার বাবার মৃত্যু সম্পর্কে আমরা কথা বলতাম। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং যদি তিনি তার ভাইয়ের শান্তি ফিরে আসেন, তাহলে তিনি আত্মসমর্পণ করবেন। লর্ড জিতে গেছেন এবং তাই করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سِنَانٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي سَوْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏عَادَ ‏ ‏الْمُسْلِمُ أَخَاهُ أَوْ زَارَهُ قَالَ اللَّهُ عَزَّ وَجَلَّ طِبْتَ وَطَابَ مَمْشَاكَ ‏ ‏وَتَبَوَّأْتَ ‏ ‏فِي الْجَنَّةِ مَنْزِلًا ‏","","",""],[8181,8181,"","আমরা আমার বাবার সাথে কথা বলেছিলাম আমার বাবা একজন পলাতকের ব্যাপারে, যে আমাদের বলত আমি যদি তার সাথে খেলতে পারি তাহলে সে বলবে আমি তার সাথে খেলতে পারব. সে বলল আমার দুটি প্রতিবেশী আছে. আমি চলে যাই. আমি আমার বাবার সাথে দেখা করতে গিয়েছিলাম. আমি তাকে বলেছিলাম. আমি যদি তার সাথে আমার দুই প্রতিবেশী থাকে. আমি এটা নিয়ে কথা বলি. আমি আমার বাবার সাথে কথা বলি. আমি তাকে বললাম. আমি যদি আমার বাবার সাথে কথা বলি. আমি আমার বাবার সাথে \"আমি যদি আমার বাবা\" আর \"আমি যদি আমার বাবা\" বলে যাই তাহলে আমি তাকে \"আমি \"আমি \"আমি\" বলতে চাই\" আর \"আমি \"আমি \"আমি\" বলতে পারি যে,\" তাদের মধ্যে একজন.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَطَاعَ الْعَبْدُ رَبَّهُ وَسَيِّدَهُ فَلَهُ أَجْرَانِ ‏ ‏قَالَ ‏ ‏فَلَمَّا أُعْتِقَ ‏ ‏أَبُو رَافِعٍ ‏ ‏بَكَى فَقِيلَ لَهُ مَا ‏ ‏يُبْكِيكَ قَالَ كَانَ لِي أَجْرَانِ فَذَهَبَ أَحَدُهُمَا ‏","","",""],[8182,8182,"","আমরা আমার বাবার কথা বলেছিলাম আমার বাবা একজন পলাতকের ব্যাপারে... ...যে আমাদের বলত, সে আমাদের শান্তি চায়। সে বলবে সে তোমার রাত আর নদীর ফল ভোগ করবে। ঈশ্বর জয় করেছেন এবং তারা আপনার কাছ থেকে এসেছে ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَجْتَمِعُ مَلَائِكَةُ اللَّيْلِ وَمَلَائِكَةُ النَّهَارِ عِنْدَ صَلَاةِ الْفَجْرِ وَصَلَاةِ الْعَصْرِ فَإِذَا عَرَجَتْ مَلَائِكَةُ النَّهَارِ قَالَ اللَّهُ عَزَّ وَجَلَّ لَهُمْ ‏ ‏مِنْ أَيْنَ جِئْتُمْ فَيَقُولُونَ جِئْنَاكَ مِنْ عِنْدِ عِبَادِكَ أَتَيْنَاهُمْ وَهُمْ يُصَلُّونَ وَجِئْنَاكَ وَهُمْ يُصَلُّونَ فَإِذَا عَرَجَتْ مَلَائِكَةُ اللَّيْلِ قَالَ اللَّهُ عَزَّ وَجَلَّ لَهُمْ مِنْ أَيْنَ جِئْتُمْ قَالُوا جِئْنَاكَ مِنْ عِنْدِ عِبَادِكَ أَتَيْنَاهُمْ وَهُمْ يُصَلُّونَ وَجِئْنَاكَ وَهُمْ يُصَلُّونَ ‏","","",""],[8183,8183,"","ঈশ্বর আপনার এবং হাতে যে - চোখ আছে, তা তুলে ধরতে সাহায্য করবেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعَيْنَانِ تَزْنِيَانِ وَالْيَدَانِ تَزْنِيَانِ وَالْفَرْجُ يُصَدِّقُ ذَلِكَ أَوْ يُكَذِّبُهُ ‏","","",""],[8184,8184,"","আমরা দুজন ঘোড়া নিয়ে কথা বলেছিলাম তাকে মৃত অবস্থায় খুঁজে নিয়ে। ঈশ্বর, ঈশ্বর, তাকে বলতে হবে, সে বলবে, সে বলবে, তাকে বলতে হবে, আমি তাকে বলিনি তুমি বাইরে যেতে এবং সেখানে যেতে যেতে দেখেছ। সে বলল আমার বাবা একটা উপহার যে সে তার মধ্যে এই প্রচেষ্টা দেখেছে। ভাঁজ করো।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جُحَادَةَ ‏ ‏أَنَّ ‏ ‏أَبَا حَصِينٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏ذَكْوَانَ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ عَلِّمْنِي عَمَلًا ‏ ‏يَعْدِلُ ‏ ‏الْجِهَادَ قَالَ لَا أَجِدُهُ قَالَ ‏ ‏هَلْ تَسْتَطِيعُ إِذَا خَرَجَ الْمُجَاهِدُ أَنْ تَدْخُلَ مَسْجِدًا فَتَقُومَ لَا ‏ ‏تَفْتُرُ ‏ ‏وَتَصُومَ لَا تُفْطِرُ قَالَ لَا أَسْتَطِيعُ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏إِنَّ فَرَسَ الْمُجَاهِدِ ‏ ‏يَسْتَنُّ ‏ ‏فِي طِوَلِهِ فَيُكْتَبُ لَهُ حَسَنَاتٍ ‏","","",""],[8185,8185,"","আমরা আমাদের আলোচনা আর বাবা মা তার ভালবাসা কথা বলেছিলাম। ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং তিনি বলেছিলেন যে, তুমি একটা ছেলের সঙ্গে দেখা করবে ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏جَدِّي أَبُو أُمِّي ‏ ‏أَبُو حَبِيبَةَ ‏ ‏أَنَّهُ ‏ ‏دَخَلَ الدَّارَ ‏ ‏وَعُثْمَانُ ‏ ‏مَحْصُورٌ فِيهَا وَأَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَسْتَأْذِنُ ‏ ‏عُثْمَانَ ‏ ‏فِي الْكَلَامِ فَأَذِنَ لَهُ فَقَامَ فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّكُمْ تَلْقَوْنَ بَعْدِي فِتْنَةً وَاخْتِلَافًا ‏ ‏أَوْ قَالَ اخْتِلَافًا وَفِتْنَةً ‏ ‏فَقَالَ لَهُ قَائِلٌ مِنْ النَّاسِ فَمَنْ لَنَا يَا رَسُولَ اللَّهِ قَالَ عَلَيْكُمْ بِالْأَمِينِ وَأَصْحَابِهِ وَهُوَ يُشِيرُ إِلَى ‏ ‏عُثْمَانَ ‏ ‏بِذَلِكَ ‏","","",""],[8186,8186,"","আমরা ব্যাপ্টিস্টদের স্বপ্ন নিয়ে কথা বলেছি ব্যাপ্টিস্টদের সম্পর্কে আমাদের বলা হয়েছে, যে মানুষকে উদ্ধার করতে হবে... সকল দেবতা, পোশাকও","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِلرَّجُلِ مِنْ أَهْلِ الْجَنَّةِ زَوْجَتَانِ مِنْ حُورِ الْعِينِ عَلَى كُلِّ وَاحِدَةٍ سَبْعُونَ حُلَّةً يُرَى مُخُّ سَاقِهَا مِنْ وَرَاءِ الثِّيَابِ ‏","","",""],[8187,8187,"","আমরা বাবার সাথে আমার বাবার সম্পর্কে কথা বলেছিলাম, আমার বাবার সাথে দেবী হওয়ার কথা ছিল। তার শান্তি আছে, সে একজন মানুষকে তার অনুসরণ করে ভূতকে হত্যা করতে ভালোবাসে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى رَجُلًا يَتْبَعُ حَمَامَةً فَقَالَ شَيْطَانٌ يَتْبَعُ شَيْطَانَةً ‏","","",""],[8188,8188,"","আমরা আমাদের নিজেদের রক্ষা করার চেষ্টা করেছি কিন্তু একজন শিকারী কখনো দেখা করেনি। আমি বলছি না যে ঈশ্বর তার কাছে প্রার্থনা করেছেন যাতে তারা প্রাণ হারিয়েছে। আমি নিশ্চিত যে আমি মানুষকে হত্যা করতে চেয়েছিলাম। আমি তাদের জীবন বাঁচানোর জন্য, আমি দৃঢ়সংকল্পবদ্ধ। আমি সিদ্ধান্ত নিয়েছি, আমি আমার নিজের জীবন বাঁচানোর জন্য। আমি সিদ্ধান্ত নিয়েছি। ঈশ্বর এবং কনের কাছে ইচ্ছা উৎসর্গ করে তা প্রত্যাখ্যান করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ كَثِيرِ بْنِ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ وَيُقِيمُوا الصَّلَاةَ وَيُؤْتُوا الزَّكَاةَ ثُمَّ قَدْ حَرَّمَ عَلَيَّ دِمَاءَهُمْ وَأَمْوَالَهُمْ وَحِسَابُهُمْ عَلَى اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[8189,8189,"","আমরা কথা বলেছিলাম একটা ছেলেকে খুঁজে পাবার ভয়ে ভীত হয়ে বাবার কাছে হারপারকে জিজ্ঞেস করবো... ...যে তার প্রভুর প্রার্থনা শোনে... তুমি যদি এটা করতে ব্যর্থ হও, তাহলে সে তাকে ক্ষমা করতে ভয় পেত।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْجُلَاسِ عُقْبَةُ بْنُ يَسَارٍ ‏ ‏حَدَّثَنِي ‏ ‏عُثْمَانُ بْنُ شَمَّاخٍ ‏ ‏قَالَ ‏ ‏شَهِدْتُ ‏ ‏مَرْوَانَ ‏ ‏سَأَلَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏كَيْفَ سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى الْجِنَازَةِ فَقَالَ مَعَ الَّذِي قُلْتُ قَالَ نَعَمْ قَالَ ‏ ‏اللَّهُمَّ أَنْتَ رَبُّهَا وَأَنْتَ خَلَقْتَهَا وَأَنْتَ هَدَيْتَهَا لِلْإِسْلَامِ وَأَنْتَ قَبَضْتَ رُوحَهَا وَأَنْتَ أَعْلَمُ بِسِرِّهَا وَعَلَانِيَتِهَا جِئْنَا شُفَعَاءَ فَاغْفِرْ لَهَا ‏","","",""],[8190,8190,"","আমি আমার বাবার কথা শুনেছি, আমি তোমার কাছে প্রার্থনা করব, আমি তোমাকে প্রার্থনা করব, আর তারা আমাকে যা কিছু বলে তাতে তোমার প্রার্থনা করব। বিশ্বাস করো তুমি কখনো পৃথিবীর থেকে খাবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِيَّاكُمْ ‏ ‏وَالْوِصَالَ ‏ ‏مَرَّتَيْنِ قَالُوا فَإِنَّكَ ‏ ‏تُوَاصِلُ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ إِنِّي لَسْتُ فِي ذَلِكَ مِثْلَكُمْ إِنِّي أَبِيتُ يُطْعِمُنِي رَبِّي وَيَسْقِينِي فَلَا تُكَلِّفُوا أَنْفُسَكُمْ مِنْ الْعَمَلِ مَا لَيْسَ لَكُمْ بِهِ طَاقَةٌ ‏","","",""],[8191,8191,"","আমরা আমার বাবার কথা বলেছিলাম, সে বলবে যে কুকুরকে তার সব ভাল কুকুর নিয়ে নি, আর শিকারী না, আর আমি মনে করি সে গাড়িটার কথা বলে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اتَّخَذَ كَلْبًا لَيْسَ بِكَلْبِ زَرْعٍ وَلَا صَيْدٍ وَلَا مَاشِيَةٍ فَإِنَّهُ يَنْقُصُ مِنْ أَجْرِهِ كُلَّ يَوْمٍ قِيرَاطٌ ‏ ‏قَالَ ‏ ‏سُلَيْمٌ ‏ ‏وَأَحْسَبُهُ قَدْ قَالَ وَالْقِيرَاطُ مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[8192,8192,"","আমরা আমার ভাই হিসেবে আমার ছেলের প্রতি বিদ্বেষ দেখানোর ব্যাপারে কথা বলেছি। ঈশ্বর মিথ্যা বলা বা মিথ্যা বলা তরুণদের মিথ্যা বলায় বলায় বলেন এবং আমি মিথ্যা বলেছি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏فَرْقَدٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏أَخِي ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ أَكْذَبُ ‏ ‏أَوْ مِنْ أَكْذَبِ ‏ ‏النَّاسِ الصَّبَّاغِينَ وَالصَّوَّاغِينَ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً إِنَّ مِنْ أَكْذَبِ ‏","","",""],[8193,8193,"","ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং একদিনে সেই ব্যক্তির কাছে গিয়ে বলেন যে, আপনি অন্য কোনো কিছু খুঁজে পেয়েছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ كَثِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ ‏ ‏أَيُصَلِّي الرَّجُلُ فِي ثَوْبٍ وَاحِدٍ فَقَالَ ‏ ‏أَوَكُلُّكُمْ يَجِدُ ثَوْبَيْنِ ‏","","",""],[8194,8194,"","বাবার সাথে আমার বাবার একটা দীর্ঘ স্বপ্নের কথা বলেছিলাম, কিন্তু সে চলে গেছে। আমি আমার বাবার এক চতুর্থাংশের কথা শুনেছি যে তার জন্য ঈশ্বরের কাছে পাঠানো হয়েছে। শিক্ষা, ঋণের বিনিময়ে সে তার সকালের নাস্তা পেয়েছে আর তাকে শেষ পর্যন্ত মুক্তি দেয়া হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏و حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ثَابِتًا ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِلصَّائِمِ فَرْحَتَانِ فَرْحَةٌ فِي الدُّنْيَا عِنْدَ إِفْطَارِهِ وَفَرْحَةٌ فِي الْآخِرَةِ ‏","","",""],[8195,8195,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং প্রার্থনায় তার কাছে সমর্পণ করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَنْبَأَنَا ‏ ‏عِسْلُ بْنُ سُفْيَانَ التَّمِيمِيُّ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏السَّدْلِ ‏ ‏فِي الصَّلَاةِ ‏","","",""],[8196,8196,"","আমাদের আলোচনা নিয়ে আমরা কথা বলেছি, আর আমরা কয়েক সপ্তাহ ধরে কাজ করেছি। তাঁর শক্তি আর আমার ছেলের একটা প্লট তার কাছে প্রার্থনা করেছে তার কল্পনার মাধ্যমে আর আত্মসমর্পণ করে দিতে পারে ক্ষমতার শক্তি, আমি এটা পরতে যাচ্ছি এবং সকালে প্রার্থনা করছি প্রথম স্থানে দ্বিতীয় এবং দ্বিতীয় সুযোগ, দুই ছেলে আমার ক্ষমতা হত্যা করেছে, ভাববাদী ঈশ্বরের কাছে প্রার্থনা করেছিলেন, তিনি ঈশ্বরের কাছে প্রার্থনা করতেন, তাদের অংশ ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏خُثَيْمٌ يَعْنِي ابْنَ عِرَاكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَدِمَ ‏ ‏الْمَدِينَةَ ‏ ‏فِي ‏ ‏رَهْطٍ ‏ ‏مِنْ قَوْمِهِ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِخَيْبَرَ ‏ ‏وَقَدْ اسْتَخْلَفَ ‏ ‏سِبَاعَ بْنَ عُرْفُطَةَ ‏ ‏عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ فَانْتَهَيْتُ إِلَيْهِ وَهُوَ يَقْرَأُ فِي صَلَاةِ الصُّبْحِ فِي الرَّكْعَةِ الْأُولَى بْ ‏ ‏كهيعص ‏ ‏وَفِي الثَّانِيَةِ ‏ ‏وَيْلٌ لِلْمُطَفِّفِينَ ‏ ‏قَالَ فَقُلْتُ لِنَفْسِي وَيْلٌ لِفُلَانٍ إِذَا اكْتَالَ اكْتَالَ بِالْوَافِي ‏ ‏وَإِذَا كَالَ كَالَ بِالنَّاقِصِ قَالَ فَلَمَّا صَلَّى زَوَّدَنَا شَيْئًا حَتَّى أَتَيْنَا ‏ ‏خَيْبَرَ ‏ ‏وَقَدْ ‏ ‏افْتَتَحَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْبَرَ ‏ ‏قَالَ فَكَلَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُسْلِمِينَ فَأَشْرَكُونَا فِي سِهَامِهِمْ ‏","","",""],[8197,8197,"","আমরা আমাদের সময় রক্ষা করার চেষ্টা করেছি এবং আমার জন্য কথা বলেছি, ঈশ্বর তার জন্য প্রার্থনা করবেন এবং তিনি আত্মসমর্পণ করবেন যে তারা তার শয়তানের হাত থেকে রক্ষা পাবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَعَوَّذُوا بِاللَّهِ مِنْ شَرِّ جَارِ الْمَقَامِ فَإِنَّ جَارَ الْمُسَافِرِ إِذَا شَاءَ أَنْ يُزَالَ زَالَ ‏","","",""],[8198,8198,"","ঈশ্বর আমার আদেশ পালন করেছেন, নাকি আমাকে স্মরণ করা হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَوْلِهِ لِرَسُولِهِ ‏ { ‏فَاسْأَلْهُ مَا ‏ ‏بَالُ ‏ ‏النِّسْوَةِ اللَّاتِي قَطَّعْنَ أَيْدِيَهُنَّ ‏} ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كُنْتُ أَنَا لَأَسْرَعْتُ الْإِجَابَةَ وَمَا ابْتَغَيْتُ الْعُذْرَ ‏","","",""],[8199,8199,"","ঈশ্বর আছেন এবং আমি যদি আমার সমস্ত হাতে বিশ্বাস করি, তা হলে আমি বিশ্বাস করব ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ آمَنَ بِي عَشْرَةٌ مِنْ ‏ ‏أَحْبَارِ ‏ ‏الْيَهُودِ ‏ ‏لَآمَنَ بِي كُلُّ يَهُودِيٍّ عَلَى وَجْهِ الْأَرْضِ ‏","","",""],[8200,8200,"","আমি বাবার সঙ্গে সারাজীবন ধরে কথা বলেছিলাম যে, তিনি ছিলেন মন্দ । ( ১ যোহন ৫: ১৯) কিন্তু, ঈশ্বরের প্রতি তার আনুগত্যের কারণে তিনি তার প্রতি অনুগত ছিলেন । আর সে যদি বলে যে ঈশ্বর তাকে ভালো কিছু বলবেন তাহলে আমি ঈশ্বরকে দেখতে পাব না। আমি তাকে বলতে দেব না যে, ফ্ল্যাশটা ক্রুশে মারা হয়েছে। ঈশ্বর তার সঙ্গে দেখা করতে বাতিল করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏قَالَ قَالَ ‏ ‏شُرَيْحُ بْنُ هَانِئٍ ‏ ‏بَيْنَمَا أَنَا فِي ‏ ‏مَسْجِدِ الْمَدِينَةِ ‏ ‏إِذْ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يُحِبُّ رَجُلٌ لِقَاءَ اللَّهِ عَزَّ وَجَلَّ إِلَّا أَحَبَّ اللَّهُ لِقَاءَهُ وَلَا أَبْغَضَ رَجُلٌ لِقَاءَ اللَّهِ إِلَّا أَبْغَضَ اللَّهُ لِقَاءَهُ فَأَتَيْتُ ‏ ‏عَائِشَةَ ‏ ‏فَقُلْتُ لَئِنْ كَانَ مَا ذَكَرَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَقًّا لَقَدْ هَلَكْنَا فَقَالَتْ إِنَّمَا الْهَالِكُ مَنْ هَلَكَ فِيمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا ذَاكَ قَالَ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ لَا يُحِبُّ رَجُلٌ لِقَاءَ اللَّهِ إِلَّا أَحَبَّ اللَّهُ لِقَاءَهُ وَلَا أَبْغَضَ رَجُلٌ لِقَاءَ اللَّهِ إِلَّا أَبْغَضَ اللَّهُ لِقَاءَهُ قَالَتْ وَأَنَا أَشْهَدُ أَنِّي سَمِعْتُهُ يَقُولُ ذَلِكَ فَهَلْ تَدْرِي لِمَ ذَلِكَ إِذَا ‏ ‏حَشْرَجَ ‏ ‏الصَّدْرُ ‏ ‏وَطَمَحَ ‏ ‏الْبَصَرُ وَاقْشَعَرَّ الْجِلْدُ وَتَشَنَّجَتْ الْأَصَابِعُ فَعِنْدَ ذَلِكَ مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللَّهُ لِقَاءَهُ وَمَنْ أَبْغَضَ لِقَاءَ اللَّهِ أَبْغَضَ اللَّهُ لِقَاءَهُ ‏","","",""]];
